{
  "name": "Minimal Sudoku",
  "description": "A Zen-inspired, minimalist Sudoku application with persistent progress, themes, and a calm mobile-first design."
}

export enum Difficulty {
  SuperEasy = 'Super Easy',
  Easy = 'Easy',
  Normal = 'Normal',
  Hard = 'Hard',
  Intense = 'Intense',
  Impossible = 'Impossible',
}

export type CellValue = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 | 9 | null;

export interface Cell {
  row: number;
  col: number;
  value: CellValue;
  isFixed: boolean;
  notes: number[];
  isError?: boolean;
}

export type Board = Cell[][];

export interface LevelProgress {
  levelId: number; // 1 to 30
  difficulty: Difficulty;
  status: 'locked' | 'not-started' | 'in-progress' | 'completed';
  timeElapsed: number;
  lastPlayed?: number; // timestamp
  boardState?: Cell[][]; // simplified for storage
  history?: any[]; // optional undo stack
}

export interface AppSettings {
  music: boolean;
  sound: boolean;
  highlight: boolean;
  autoNotes: boolean;
}

export interface StoredData {
  settings: AppSettings;
  progress: Record<string, LevelProgress>; // key: "Difficulty-LevelID"
}

import { Difficulty, Board, Cell, CellValue } from '../types';

const BLANK: CellValue = null;

// Helper to check if placing num at board[row][col] is valid
function isValid(board: number[][], row: number, col: number, num: number): boolean {
  for (let i = 0; i < 9; i++) {
    if (board[row][i] === num && i !== col) return false;
    if (board[i][col] === num && i !== row) return false;
    const boxRow = 3 * Math.floor(row / 3) + Math.floor(i / 3);
    const boxCol = 3 * Math.floor(col / 3) + (i % 3);
    if (board[boxRow][boxCol] === num && (boxRow !== row || boxCol !== col)) return false;
  }
  return true;
}

// Solves/Generates a board using backtracking
function solveBoard(board: number[][]): boolean {
  for (let row = 0; row < 9; row++) {
    for (let col = 0; col < 9; col++) {
      if (board[row][col] === 0) {
        // Randomize 1-9 check order for randomness
        const nums = [1, 2, 3, 4, 5, 6, 7, 8, 9].sort(() => Math.random() - 0.5);
        for (const num of nums) {
          if (isValid(board, row, col, num)) {
            board[row][col] = num;
            if (solveBoard(board)) return true;
            board[row][col] = 0;
          }
        }
        return false;
      }
    }
  }
  return true;
}

// Generate a full solved board
function generateFullBoard(seed: number): number[][] {
    // Simple pseudo-random seeding for consistency across "levels"
    // In a real app we might use a better PRNG. 
    // Here we just use Math.random() but seeded by logic in the caller usually. 
    // For this implementation, we will rely on runtime generation which is "random enough".
    const board = Array.from({ length: 9 }, () => Array(9).fill(0));
    solveBoard(board);
    return board;
}

export function generateLevel(difficulty: Difficulty, levelId: number): { initial: Board, solved: number[][] } {
    // Determine number of holes based on difficulty
    let holes = 30; 
    switch(difficulty) {
        case Difficulty.SuperEasy: holes = 25; break;
        case Difficulty.Easy: holes = 35; break;
        case Difficulty.Normal: holes = 42; break;
        case Difficulty.Hard: holes = 50; break;
        case Difficulty.Intense: holes = 56; break;
        case Difficulty.Impossible: holes = 60; break;
    }

    // Generate full board
    const solvedRaw = generateFullBoard(levelId);
    // Deep copy for puzzle
    const puzzleRaw = solvedRaw.map(r => [...r]);

    // Remove numbers to create holes
    let attempts = holes;
    while (attempts > 0) {
        const r = Math.floor(Math.random() * 9);
        const c = Math.floor(Math.random() * 9);
        if (puzzleRaw[r][c] !== 0) {
            puzzleRaw[r][c] = 0;
            attempts--;
        }
    }

    // Convert to rich Cell objects
    const initial: Board = puzzleRaw.map((row, rIndex) => 
        row.map((val, cIndex) => ({
            row: rIndex,
            col: cIndex,
            value: val === 0 ? null : (val as CellValue),
            isFixed: val !== 0,
            notes: [],
            isError: false
        }))
    );

    return { initial, solved: solvedRaw };
}

export function checkErrors(current: Board, solved: number[][]): Board {
    return current.map(row => 
        row.map(cell => ({
            ...cell,
            isError: cell.value !== null && cell.value !== solved[cell.row][cell.col]
        }))
    );
}

export function isGameSolved(current: Board): boolean {
    for(let r=0; r<9; r++) {
        for(let c=0; c<9; c++) {
            const cell = current[r][c];
            if (cell.value === null || cell.isError) return false;
            // Also simplistic check: conflict logic is handled by isError usually, 
            // but we assume if board is full and no errors (or validated against solved), it's done.
        }
    }
    return true;
}

import { AppSettings, LevelProgress, StoredData } from '../types';

const STORAGE_KEY = 'minimal_sudoku_data_v1';

const DEFAULT_SETTINGS: AppSettings = {
  music: false,
  sound: true,
  highlight: true,
  autoNotes: false,
};

function getStoredData(): StoredData {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      return { settings: DEFAULT_SETTINGS, progress: {} };
    }
    return JSON.parse(raw);
  } catch (e) {
    console.error("Failed to load data", e);
    return { settings: DEFAULT_SETTINGS, progress: {} };
  }
}

function saveData(data: StoredData) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch (e) {
    console.error("Failed to save data", e);
  }
}

export const Storage = {
  getSettings: (): AppSettings => {
    return getStoredData().settings;
  },

  saveSettings: (settings: AppSettings) => {
    const data = getStoredData();
    data.settings = settings;
    saveData(data);
  },

  getLevelProgress: (difficulty: string, levelId: number): LevelProgress | undefined => {
    const key = `${difficulty}-${levelId}`;
    return getStoredData().progress[key];
  },

  saveLevelProgress: (progress: LevelProgress) => {
    const data = getStoredData();
    const key = `${progress.difficulty}-${progress.levelId}`;
    data.progress[key] = progress;
    saveData(data);
  },

  clearLevelProgress: (difficulty: string, levelId: number) => {
      const data = getStoredData();
      const key = `${difficulty}-${levelId}`;
      if (data.progress[key]) {
          // Reset to not-started or just remove the 'in-progress' state
          // Usually we want to keep 'completed' status.
          // This function is for "Restart Level"
           data.progress[key] = {
               ...data.progress[key],
               status: 'not-started',
               boardState: undefined,
               timeElapsed: 0,
               history: []
           }
           saveData(data);
      }
  },

  resetAllData: () => {
    localStorage.removeItem(STORAGE_KEY);
  },

  // Get counts for UI
  getCompletedCount: (difficulty: string): number => {
      const progress = getStoredData().progress;
      return Object.values(progress).filter(p => p.difficulty === difficulty && p.status === 'completed').length;
  }
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Board, Cell, Difficulty, LevelProgress } from '../types';
import { generateLevel, checkErrors, isGameSolved } from '../utils/sudoku';
import { Storage } from '../utils/storage';
import { Icons } from './ui/Icons';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onComplete: () => void;
  settings: any;
}

export const SudokuGame: React.FC<SudokuGameProps> = ({ difficulty, levelId, onBack, onComplete, settings }) => {
  const [board, setBoard] = useState<Board>([]);
  const [solvedBoard, setSolvedBoard] = useState<number[][]>([]);
  const [selectedCell, setSelectedCell] = useState<[number, number] | null>(null);
  const [isPencilMode, setIsPencilMode] = useState(false);
  const [history, setHistory] = useState<Board[]>([]);
  const [timer, setTimer] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [loading, setLoading] = useState(true);

  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Initialize Game
  useEffect(() => {
    const loadGame = () => {
      setLoading(true);
      const savedProgress = Storage.getLevelProgress(difficulty, levelId);

      if (savedProgress && savedProgress.status === 'in-progress' && savedProgress.boardState) {
        setBoard(savedProgress.boardState);
        setTimer(savedProgress.timeElapsed);
        // We need the solved board to validate. 
        // In a stateless generator, we'd need to re-generate the same board based on seed.
        // For this demo, we re-generate. If the seed matches levelId, it works.
        const { solved } = generateLevel(difficulty, levelId); 
        setSolvedBoard(solved);
      } else {
        const { initial, solved } = generateLevel(difficulty, levelId);
        setBoard(initial);
        setSolvedBoard(solved);
        setTimer(0);
      }
      setLoading(false);
    };

    loadGame();
    return () => stopTimer();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [difficulty, levelId]);

  // Timer Logic
  const startTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = setInterval(() => {
      setTimer((t) => t + 1);
    }, 1000);
  };

  const stopTimer = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  useEffect(() => {
    if (!loading && !isPaused && !isCompleted) {
      startTimer();
    } else {
      stopTimer();
    }
    return () => stopTimer();
  }, [loading, isPaused, isCompleted]);

  // Auto-save
  useEffect(() => {
    if (loading || isCompleted) return;

    const save = setTimeout(() => {
      const progress: LevelProgress = {
        levelId,
        difficulty,
        status: 'in-progress',
        timeElapsed: timer,
        lastPlayed: Date.now(),
        boardState: board,
      };
      Storage.saveLevelProgress(progress);
    }, 1000);

    return () => clearTimeout(save);
  }, [board, timer, difficulty, levelId, loading, isCompleted]);


  const handleCellClick = (row: number, col: number) => {
    if (isPaused) return;
    setSelectedCell([row, col]);
  };

  const handleNumberInput = (num: number) => {
    if (!selectedCell || isPaused || isCompleted) return;
    const [r, c] = selectedCell;
    const currentCell = board[r][c];

    if (currentCell.isFixed) return;

    // Push to history
    setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);

    const newBoard = [...board];
    const newCell = { ...newBoard[r][c] };

    if (isPencilMode) {
      // Toggle note
      if (newCell.notes.includes(num)) {
        newCell.notes = newCell.notes.filter(n => n !== num);
      } else {
        newCell.notes = [...newCell.notes, num].sort();
      }
    } else {
      // Set value
      if (newCell.value === num) {
        newCell.value = null; // Toggle off if same
        newCell.isError = false;
      } else {
        newCell.value = num as any;
        // Check immediate error
        newCell.isError = num !== solvedBoard[r][c];

        // Clear notes in row/col/box if auto-notes setting (optional feature) or manual logic
        // For now, let's just clear notes in this specific cell
        newCell.notes = [];
      }
    }

    newBoard[r][c] = newCell;
    setBoard(newBoard);

    // Check Win Condition
    if (!isPencilMode && newCell.value) {
       checkCompletion(newBoard);
    }
  };

  const checkCompletion = (currentBoard: Board) => {
      // Simple check: is board full and error free?
      // Real robust check uses `solvedBoard`
      let filled = 0;
      let correct = 0;
      for(let r=0; r<9; r++) {
          for(let c=0; c<9; c++) {
              if (currentBoard[r][c].value !== null) {
                  filled++;
                  if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
              }
          }
      }

      if (filled === 81 && correct === 81) {
          setIsCompleted(true);
          stopTimer();

          // Save completion
          const progress: LevelProgress = {
            levelId,
            difficulty,
            status: 'completed',
            timeElapsed: timer,
            lastPlayed: Date.now(),
            boardState: undefined, // Clear state to save space
          };
          Storage.saveLevelProgress(progress);
      }
  };

  const handleErase = () => {
    if (!selectedCell || isPaused) return;
    const [r, c] = selectedCell;
    if (board[r][c].isFixed) return;

    setHistory(prev => [...prev, JSON.parse(JSON.stringify(board))]);
    const newBoard = [...board];
    newBoard[r][c].value = null;
    newBoard[r][c].notes = [];
    newBoard[r][c].isError = false;
    setBoard(newBoard);
  };

  const handleUndo = () => {
    if (history.length === 0 || isPaused) return;
    const previous = history[history.length - 1];
    setBoard(previous);
    setHistory(prev => prev.slice(0, -1));
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Helper for highlighting
  const getCellClass = (cell: Cell, r: number, c: number) => {
    let base = "w-full h-full flex items-center justify-center text-lg sm:text-2xl transition-colors duration-200 cursor-pointer select-none relative ";

    // Grid borders
    const borderR = (c + 1) % 3 === 0 && c !== 8 ? "border-r-2 border-stone-300" : "border-r border-stone-200";
    const borderB = (r + 1) % 3 === 0 && r !== 8 ? "border-b-2 border-stone-300" : "border-b border-stone-200";
    // Fix outer borders in parent grid, so just handle inner here or let parent handle grid gap
    // Actually, using border on cells is easiest for Sudoku

    base += `${borderR} ${borderB} `;

    if (selectedCell) {
        const [sr, sc] = selectedCell;
        const isSelected = sr === r && sc === c;
        const isRelated = sr === r || sc === c || (Math.floor(sr/3) === Math.floor(r/3) && Math.floor(sc/3) === Math.floor(c/3));
        const isSameValue = cell.value !== null && board[sr][sc].value === cell.value;

        if (isSelected) {
            base += "bg-blue-500 text-white ";
        } else if (settings.highlight && isSameValue) {
            base += "bg-blue-200 ";
        } else if (settings.highlight && isRelated) {
            base += "bg-stone-100 ";
        } else {
             base += "bg-white ";
        }
    } else {
        base += "bg-white ";
    }

    if (cell.isError) {
        // If selected, maybe keep blue but red text? Or red bg.
        // Let's make error red text if selected, red bg if not?
        if (selectedCell && selectedCell[0] === r && selectedCell[1] === c) {
            // keep blue bg
        } else {
            base = base.replace("bg-stone-100", "bg-red-50").replace("bg-white", "bg-red-50");
            base += "text-red-500 ";
        }
    } else if (cell.isFixed) {
        base += "font-semibold text-stone-900 ";
    } else {
        base += "font-medium text-blue-600 ";
    }

    return base;
  };

  if (loading) return <div className="h-full w-full flex items-center justify-center">Loading...</div>;

  return (
    <div className="h-full flex flex-col max-w-lg mx-auto p-4 relative animate-fade-in">
      {/* Header */}
      <div className="flex justify-between items-center mb-6">
        <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition">
          <Icons.Back className="w-6 h-6 text-stone-600" />
        </button>
        <div className="flex flex-col items-center">
            <span className="text-xs font-bold tracking-wider text-stone-400 uppercase">{difficulty}</span>
            <span className="text-xl font-medium tabular-nums text-stone-700">{formatTime(timer)}</span>
        </div>
        <div className="flex gap-2">
            <button onClick={() => setIsPaused(true)} className="p-2 rounded-full hover:bg-stone-200 transition">
            <Icons.Pause className="w-6 h-6 text-stone-600" />
            </button>
        </div>
      </div>

      {/* Board */}
      <div className="aspect-square w-full bg-stone-300 border-2 border-stone-300 rounded-lg overflow-hidden shadow-sm">
        <div className="grid grid-rows-9 h-full">
          {board.map((row, rIndex) => (
            <div key={rIndex} className="grid grid-cols-9 h-full">
              {row.map((cell, cIndex) => (
                <div 
                    key={`${rIndex}-${cIndex}`} 
                    className={getCellClass(cell, rIndex, cIndex)}
                    onClick={() => handleCellClick(rIndex, cIndex)}
                >
                  {cell.value ? (
                      <span>{cell.value}</span>
                  ) : (
                      <div className="grid grid-cols-3 w-full h-full p-0.5">
                          {[1,2,3,4,5,6,7,8,9].map(n => (
                              <div key={n} className="flex items-center justify-center text-[8px] sm:text-[10px] leading-none text-stone-500">
                                  {cell.notes.includes(n) ? n : ''}
                              </div>
                          ))}
                      </div>
                  )}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* Controls */}
      <div className="mt-8 flex flex-col gap-4">
        {/* Actions */}
        <div className="flex justify-between px-4">
            <button onClick={handleUndo} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Undo className="w-5 h-5" /></div>
                <span className="text-xs">Undo</span>
            </button>
            <button onClick={() => setIsPencilMode(!isPencilMode)} className={`flex flex-col items-center gap-1 active:scale-95 transition ${isPencilMode ? 'text-blue-500' : 'text-stone-500'}`}>
                <div className={`p-3 rounded-full shadow-sm border border-stone-100 ${isPencilMode ? 'bg-blue-50 border-blue-200' : 'bg-white'}`}>
                    <Icons.Pencil className="w-5 h-5" />
                    {isPencilMode && <span className="absolute top-0 right-0 w-2 h-2 bg-blue-500 rounded-full"></span>}
                </div>
                <span className="text-xs">Pencil</span>
            </button>
            <button onClick={handleErase} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Erase className="w-5 h-5" /></div>
                <span className="text-xs">Erase</span>
            </button>
            {/* Optional Hint Button */}
             <button className="flex flex-col items-center gap-1 text-stone-300 cursor-not-allowed">
                <div className="p-3 bg-stone-50 rounded-full border border-stone-100"><Icons.Hint className="w-5 h-5" /></div>
                <span className="text-xs">Hint</span>
            </button>
        </div>

        {/* Numpad */}
        <div className="grid grid-cols-9 gap-1 mt-2">
            {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                <button
                    key={num}
                    onClick={() => handleNumberInput(num)}
                    className="aspect-[4/5] flex items-center justify-center text-xl font-medium text-blue-600 bg-white rounded-lg shadow-sm border-b-2 border-stone-100 active:border-b-0 active:translate-y-[2px] transition-all"
                >
                    {num}
                </button>
            ))}
        </div>
      </div>

      {/* Pause Modal */}
      {isPaused && (
          <div className="absolute inset-0 bg-stone-50/90 backdrop-blur-sm z-50 flex flex-col items-center justify-center animate-fade-in">
              <h2 className="text-2xl font-bold text-stone-800 mb-8">Game Paused</h2>
              <div className="flex flex-col gap-4 w-48">
                <button onClick={() => setIsPaused(false)} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white rounded-xl shadow-lg active:scale-95 transition">
                    <Icons.Play className="w-5 h-5" /> Resume
                </button>
                <button 
                    onClick={() => {
                        Storage.clearLevelProgress(difficulty, levelId);
                        window.location.reload(); // Quick reset
                    }} 
                    className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 rounded-xl active:scale-95 transition"
                >
                    <Icons.Reset className="w-5 h-5" /> Restart Level
                </button>
                <button onClick={onBack} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 transition">
                     Quit Game
                </button>
              </div>
          </div>
      )}

      {/* Completion Modal */}
      {isCompleted && (
          <div className="absolute inset-0 bg-blue-600/90 z-50 flex flex-col items-center justify-center text-white animate-fade-in">
              <div className="bg-white text-stone-800 p-8 rounded-2xl shadow-2xl w-80 text-center animate-pop">
                  <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4 text-green-600">
                      <Icons.Check className="w-8 h-8" />
                  </div>
                  <h2 className="text-2xl font-bold mb-2">Solved!</h2>
                  <p className="text-stone-500 mb-6">Excellent work.</p>
                  <p className="text-xl font-medium mb-8">{formatTime(timer)}</p>

                  <button onClick={onBack} className="w-full py-3 bg-stone-800 text-white rounded-xl font-medium hover:bg-stone-700 transition mb-3">
                      Back to Levels
                  </button>
                  {/* Next level logic would go here, simplistic for now */}
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { Icons } from './components/ui/Icons';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings';

function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [showSettings, setShowSettings] = useState(false);

  // Splash Screen Effect
  useEffect(() => {
    const timer = setTimeout(() => {
      setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  const handleDifficultySelect = (diff: Difficulty) => {
    setSelectedDifficulty(diff);
    setScreen('levels');
  };

  const handleLevelSelect = (levelId: number) => {
    setSelectedLevel(levelId);
    setScreen('game');
  };

  const toggleSetting = (key: keyof AppSettings) => {
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  // --- Render Components ---

  // 1. Splash
  if (screen === 'splash') {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-stone-50">
        <div className="animate-fade-in flex flex-col items-center">
            <div className="w-20 h-20 bg-stone-800 rounded-2xl mb-6 shadow-xl flex items-center justify-center">
                <div className="grid grid-cols-2 gap-1">
                    <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                    <div className="w-3 h-3 bg-white rounded-sm"></div>
                    <div className="w-3 h-3 bg-white rounded-sm"></div>
                    <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                </div>
            </div>
          <h1 className="text-3xl font-light tracking-widest text-stone-800">MINIMAL</h1>
          <h2 className="text-xl font-bold tracking-widest text-stone-400">SUDOKU</h2>
        </div>
      </div>
    );
  }

  // Settings Modal Overlay
  const SettingsModal = () => (
      <div className="fixed inset-0 z-[100] bg-black/20 backdrop-blur-sm flex items-end sm:items-center justify-center animate-fade-in" onClick={() => setShowSettings(false)}>
          <div className="bg-white w-full max-w-md p-6 rounded-t-3xl sm:rounded-3xl shadow-2xl animate-slide-up" onClick={e => e.stopPropagation()}>
              <div className="flex justify-between items-center mb-6">
                  <h3 className="text-xl font-bold text-stone-800">Settings</h3>
                  <button onClick={() => setShowSettings(false)} className="p-2 bg-stone-100 rounded-full hover:bg-stone-200"><Icons.Close className="w-5 h-5" /></button>
              </div>

              <div className="space-y-4">
                  <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                      <div className="flex items-center gap-3 text-stone-700">
                          <Icons.Sound className="w-5 h-5" />
                          <span>Sound Effects</span>
                      </div>
                      <button onClick={() => toggleSetting('sound')} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings.sound ? 'bg-green-500' : 'bg-stone-300'}`}>
                          <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings.sound ? 'translate-x-5' : 'translate-x-0'}`}></div>
                      </button>
                  </div>
                  <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                      <div className="flex items-center gap-3 text-stone-700">
                          <Icons.Eye className="w-5 h-5" />
                          <span>Highlight Areas</span>
                      </div>
                      <button onClick={() => toggleSetting('highlight')} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings.highlight ? 'bg-green-500' : 'bg-stone-300'}`}>
                          <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings.highlight ? 'translate-x-5' : 'translate-x-0'}`}></div>
                      </button>
                  </div>
                  {/* More settings can go here */}
              </div>

              <div className="mt-8 pt-6 border-t border-stone-100">
                  <button onClick={resetProgress} className="w-full py-3 flex items-center justify-center gap-2 text-red-500 hover:bg-red-50 rounded-xl transition">
                      <Icons.Trash className="w-5 h-5" /> Reset All Progress
                  </button>
              </div>
          </div>
      </div>
  );

  // 2. Difficulty Selection
  if (screen === 'difficulty') {
    const difficulties = Object.values(Difficulty);
    return (
      <div className="min-h-screen bg-paper text-stone-800 p-6 flex flex-col items-center">
        <div className="w-full max-w-md flex justify-between items-center mb-8 mt-4">
            <div>
                <h1 className="text-2xl font-bold">New Game</h1>
                <p className="text-stone-400 text-sm">Select your challenge</p>
            </div>
            <button onClick={() => setShowSettings(true)} className="p-2 bg-white rounded-full shadow-sm hover:shadow-md transition">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>

        <div className="w-full max-w-md grid grid-cols-2 gap-4">
          {difficulties.map((diff) => {
             const completed = Storage.getCompletedCount(diff);
             return (
                <button
                key={diff}
                onClick={() => handleDifficultySelect(diff)}
                className="bg-white p-6 rounded-2xl shadow-sm border border-stone-100 flex flex-col items-start gap-2 hover:border-blue-200 hover:shadow-md transition-all active:scale-95 text-left"
                >
                <span className="text-lg font-semibold text-stone-700">{diff}</span>
                <span className="text-xs text-stone-400 font-medium tracking-wide">{completed} / 30 Solved</span>
                <div className="w-full h-1 bg-stone-100 rounded-full mt-2 overflow-hidden">
                    <div className="h-full bg-stone-800" style={{ width: `${(completed/30)*100}%` }}></div>
                </div>
                </button>
            )
          })}
        </div>
        {showSettings && <SettingsModal />}
      </div>
    );
  }

  // 3. Level Selection
  if (screen === 'levels' && selectedDifficulty) {
    const levels = Array.from({ length: 30 }, (_, i) => i + 1);

    // Check for unfinished level
    // In a real app we'd scan all. For now simple check.

    return (
      <div className="min-h-screen bg-paper p-6 flex flex-col items-center">
        <div className="w-full max-w-md flex items-center mb-8 mt-4 relative">
            <button onClick={() => setScreen('difficulty')} className="absolute left-0 p-2 rounded-full hover:bg-stone-200">
                <Icons.Back className="w-6 h-6" />
            </button>
            <div className="w-full text-center">
                <h1 className="text-xl font-bold">{selectedDifficulty}</h1>
                <p className="text-xs text-stone-400 uppercase tracking-widest">Select Level</p>
            </div>
             <button onClick={() => setShowSettings(true)} className="absolute right-0 p-2 rounded-full hover:bg-stone-200">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>

        <div className="w-full max-w-md grid grid-cols-5 gap-3">
          {levels.map((lvl) => {
            const progress = Storage.getLevelProgress(selectedDifficulty, lvl);
            const isCompleted = progress?.status === 'completed';
            const isInProgress = progress?.status === 'in-progress';

            return (
              <button
                key={lvl}
                onClick={() => handleLevelSelect(lvl)}
                className={`
                  aspect-square rounded-xl flex flex-col items-center justify-center relative transition-all active:scale-90
                  ${isCompleted 
                    ? 'bg-stone-200 text-stone-400' 
                    : isInProgress 
                        ? 'bg-white border-2 border-blue-400 shadow-md text-stone-800' 
                        : 'bg-white border border-stone-100 shadow-sm hover:shadow-md text-stone-800'}
                `}
              >
                <span className="font-bold text-lg">{lvl}</span>
                {isCompleted && <Icons.Check className="w-4 h-4 absolute bottom-1 text-stone-500" />}
                {isInProgress && <div className="w-1.5 h-1.5 rounded-full bg-blue-500 absolute bottom-2"></div>}
              </button>
            );
          })}
        </div>
        {showSettings && <SettingsModal />}
      </div>
    );
  }

  // 4. Game Screen
  if (screen === 'game' && selectedDifficulty && selectedLevel) {
    return (
      <div className="h-screen w-full bg-paper">
         <SudokuGame 
            difficulty={selectedDifficulty}
            levelId={selectedLevel}
            onBack={() => setScreen('levels')}
            onComplete={() => {}} // Internal modal handles navigation usually, or lift state up
            settings={settings}
         />
      </div>
    );
  }

  return null;
}

