import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Board, Cell, Difficulty, LevelProgress } from '../types';
import { generateLevel, checkErrors, isGameSolved } from '../utils/sudoku';
import { Storage } from '../utils/storage';
import { Icons } from './ui/Icons';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onComplete: () => void;
  settings: any;
}

export const SudokuGame: React.FC<SudokuGameProps> = ({ difficulty, levelId, onBack, onComplete, settings }) => {
  const [board, setBoard] = useState<Board>([]);
  const [solvedBoard, setSolvedBoard] = useState<number[][]>([]);
  const [selectedCell, setSelectedCell] = useState<[number, number] | null>(null);
  const [isPencilMode, setIsPencilMode] = useState(false);
  const [history, setHistory] = useState<Board[]>([]);
  const [timer, setTimer] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [loading, setLoading] = useState(true);

  const timerRef = useRef<any>(null);

  // Initialize Game
  useEffect(() => {
    const loadGame = () => {
      setLoading(true);
      const savedProgress = Storage.getLevelProgress(difficulty, levelId);

      if (savedProgress && savedProgress.status === 'in-progress' && savedProgress.boardState) {
        setBoard(savedProgress.boardState);
        setTimer(savedProgress.timeElapsed);
        // We need the solved board to validate. 
        // In a stateless generator, we'd need to re-generate the same board based on seed.
        // For this demo, we re-generate. If the seed matches levelId, it works.
        const { solved } = generateLevel(difficulty, levelId); 
        setSolvedBoard(solved);
      } else {
        const { initial, solved } = generateLevel(difficulty, levelId);
        setBoard(initial);
        setSolvedBoard(solved);
        setTimer(0);
      }
      setLoading(false);
    };

    loadGame();
    return () => stopTimer();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [difficulty, levelId]);

  // Timer Logic
  const startTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = setInterval(() => {
      setTimer((t) => t + 1);
    }, 1000);
  };

  const stopTimer = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  useEffect(() => {
    if (!loading && !isPaused && !isCompleted) {
      startTimer();
    } else {
      stopTimer();
    }
    return () => stopTimer();
  }, [loading, isPaused, isCompleted]);

  // Auto-save
  useEffect(() => {
    if (loading || isCompleted) return;

    const save = setTimeout(() => {
      const progress: LevelProgress = {
        levelId,
        difficulty,
        status: 'in-progress',
        timeElapsed: timer,
        lastPlayed: Date.now(),
        boardState: board,
      };
      Storage.saveLevelProgress(progress);
    }, 1000);

    return () => clearTimeout(save);
  }, [board, timer, difficulty, levelId, loading, isCompleted]);


  const handleCellClick = (row: number, col: number) => {
    if (isPaused) return;
    setSelectedCell([row, col]);
  };

  const handleNumberInput = (num: number) => {
    if (!selectedCell || isPaused || isCompleted) return;
    const [r, c] = selectedCell;
    const currentCell = board[r][c];

    if (currentCell.isFixed) return;

    // Push to history
    setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);

    const newBoard = [...board];
    const newCell = { ...newBoard[r][c] };

    if (isPencilMode) {
      // Toggle note
      if (newCell.notes.includes(num)) {
        newCell.notes = newCell.notes.filter(n => n !== num);
      } else {
        newCell.notes = [...newCell.notes, num].sort();
      }
    } else {
      // Set value
      if (newCell.value === num) {
        newCell.value = null; // Toggle off if same
        newCell.isError = false;
      } else {
        newCell.value = num as any;
        // Check immediate error
        newCell.isError = num !== solvedBoard[r][c];

        // Clear notes in row/col/box if auto-notes setting (optional feature) or manual logic
        // For now, let's just clear notes in this specific cell
        newCell.notes = [];
      }
    }

    newBoard[r][c] = newCell;
    setBoard(newBoard);

    // Check Win Condition
    if (!isPencilMode && newCell.value) {
       checkCompletion(newBoard);
    }
  };

  const checkCompletion = (currentBoard: Board) => {
      // Simple check: is board full and error free?
      // Real robust check uses `solvedBoard`
      let filled = 0;
      let correct = 0;
      for(let r=0; r<9; r++) {
          for(let c=0; c<9; c++) {
              if (currentBoard[r][c].value !== null) {
                  filled++;
                  if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
              }
          }
      }

      if (filled === 81 && correct === 81) {
          setIsCompleted(true);
          stopTimer();

          // Save completion
          const progress: LevelProgress = {
            levelId,
            difficulty,
            status: 'completed',
            timeElapsed: timer,
            lastPlayed: Date.now(),
            boardState: undefined, // Clear state to save space
          };
          Storage.saveLevelProgress(progress);
      }
  };

  const handleErase = () => {
    if (!selectedCell || isPaused) return;
    const [r, c] = selectedCell;
    if (board[r][c].isFixed) return;

    setHistory(prev => [...prev, JSON.parse(JSON.stringify(board))]);
    const newBoard = [...board];
    newBoard[r][c].value = null;
    newBoard[r][c].notes = [];
    newBoard[r][c].isError = false;
    setBoard(newBoard);
  };

  const handleUndo = () => {
    if (history.length === 0 || isPaused) return;
    const previous = history[history.length - 1];
    setBoard(previous);
    setHistory(prev => prev.slice(0, -1));
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Helper for highlighting
  const getCellClass = (cell: Cell, r: number, c: number) => {
    let base = "w-full h-full flex items-center justify-center text-lg sm:text-2xl transition-colors duration-200 cursor-pointer select-none relative ";

    // Grid borders
    const borderR = (c + 1) % 3 === 0 && c !== 8 ? "border-r-2 border-stone-300" : "border-r border-stone-200";
    const borderB = (r + 1) % 3 === 0 && r !== 8 ? "border-b-2 border-stone-300" : "border-b border-stone-200";
    // Fix outer borders in parent grid, so just handle inner here or let parent handle grid gap
    // Actually, using border on cells is easiest for Sudoku

    base += `${borderR} ${borderB} `;

    if (selectedCell) {
        const [sr, sc] = selectedCell;
        const isSelected = sr === r && sc === c;
        const isRelated = sr === r || sc === c || (Math.floor(sr/3) === Math.floor(r/3) && Math.floor(sc/3) === Math.floor(c/3));
        const isSameValue = cell.value !== null && board[sr][sc].value === cell.value;

        if (isSelected) {
            base += "bg-blue-500 text-white ";
        } else if (settings.highlight && isSameValue) {
            base += "bg-blue-200 ";
        } else if (settings.highlight && isRelated) {
            base += "bg-stone-100 ";
        } else {
             base += "bg-white ";
        }
    } else {
        base += "bg-white ";
    }

    if (cell.isError) {
        // If selected, maybe keep blue but red text? Or red bg.
        // Let's make error red text if selected, red bg if not?
        if (selectedCell && selectedCell[0] === r && selectedCell[1] === c) {
            // keep blue bg
        } else {
            base = base.replace("bg-stone-100", "bg-red-50").replace("bg-white", "bg-red-50");
            base += "text-red-500 ";
        }
    } else if (cell.isFixed) {
        base += "font-semibold text-stone-900 ";
    } else {
        base += "font-medium text-blue-600 ";
    }

    return base;
  };

  if (loading) return <div className="h-full w-full flex items-center justify-center">Loading...</div>;

  return (
    <div className="h-full flex flex-col max-w-lg mx-auto p-4 relative animate-fade-in">
      {/* Header */}
      <div className="flex justify-between items-center mb-6">
        <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition">
          <Icons.Back className="w-6 h-6 text-stone-600" />
        </button>
        <div className="flex flex-col items-center">
            <span className="text-xs font-bold tracking-wider text-stone-400 uppercase">{difficulty}</span>
            <span className="text-xl font-medium tabular-nums text-stone-700">{formatTime(timer)}</span>
        </div>
        <div className="flex gap-2">
            <button onClick={() => setIsPaused(true)} className="p-2 rounded-full hover:bg-stone-200 transition">
            <Icons.Pause className="w-6 h-6 text-stone-600" />
            </button>
        </div>
      </div>

      {/* Board */}
      <div className="aspect-square w-full bg-stone-300 border-2 border-stone-300 rounded-lg overflow-hidden shadow-sm">
        <div className="grid grid-rows-9 h-full">
          {board.map((row, rIndex) => (
            <div key={rIndex} className="grid grid-cols-9 h-full">
              {row.map((cell, cIndex) => (
                <div 
                    key={`${rIndex}-${cIndex}`} 
                    className={getCellClass(cell, rIndex, cIndex)}
                    onClick={() => handleCellClick(rIndex, cIndex)}
                >
                  {cell.value ? (
                      <span>{cell.value}</span>
                  ) : (
                      <div className="grid grid-cols-3 w-full h-full p-0.5">
                          {[1,2,3,4,5,6,7,8,9].map(n => (
                              <div key={n} className="flex items-center justify-center text-[8px] sm:text-[10px] leading-none text-stone-500">
                                  {cell.notes.includes(n) ? n : ''}
                              </div>
                          ))}
                      </div>
                  )}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* Controls */}
      <div className="mt-8 flex flex-col gap-4">
        {/* Actions */}
        <div className="flex justify-between px-4">
            <button onClick={handleUndo} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Undo className="w-5 h-5" /></div>
                <span className="text-xs">Undo</span>
            </button>
            <button onClick={() => setIsPencilMode(!isPencilMode)} className={`flex flex-col items-center gap-1 active:scale-95 transition ${isPencilMode ? 'text-blue-500' : 'text-stone-500'}`}>
                <div className={`p-3 rounded-full shadow-sm border border-stone-100 ${isPencilMode ? 'bg-blue-50 border-blue-200' : 'bg-white'}`}>
                    <Icons.Pencil className="w-5 h-5" />
                    {isPencilMode && <span className="absolute top-0 right-0 w-2 h-2 bg-blue-500 rounded-full"></span>}
                </div>
                <span className="text-xs">Pencil</span>
            </button>
            <button onClick={handleErase} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Erase className="w-5 h-5" /></div>
                <span className="text-xs">Erase</span>
            </button>
            {/* Optional Hint Button */}
             <button className="flex flex-col items-center gap-1 text-stone-300 cursor-not-allowed">
                <div className="p-3 bg-stone-50 rounded-full border border-stone-100"><Icons.Hint className="w-5 h-5" /></div>
                <span className="text-xs">Hint</span>
            </button>
        </div>

        {/* Numpad */}
        <div className="grid grid-cols-9 gap-1 mt-2">
            {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                <button
                    key={num}
                    onClick={() => handleNumberInput(num)}
                    className="aspect-[4/5] flex items-center justify-center text-xl font-medium text-blue-600 bg-white rounded-lg shadow-sm border-b-2 border-stone-100 active:border-b-0 active:translate-y-[2px] transition-all"
                >
                    {num}
                </button>
            ))}
        </div>
      </div>

      {/* Pause Modal */}
      {isPaused && (
          <div className="absolute inset-0 bg-stone-50/90 backdrop-blur-sm z-50 flex flex-col items-center justify-center animate-fade-in">
              <h2 className="text-2xl font-bold text-stone-800 mb-8">Game Paused</h2>
              <div className="flex flex-col gap-4 w-48">
                <button onClick={() => setIsPaused(false)} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white rounded-xl shadow-lg active:scale-95 transition">
                    <Icons.Play className="w-5 h-5" /> Resume
                </button>
                <button 
                    onClick={() => {
                        Storage.clearLevelProgress(difficulty, levelId);
                        window.location.reload(); // Quick reset
                    }} 
                    className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 rounded-xl active:scale-95 transition"
                >
                    <Icons.Reset className="w-5 h-5" /> Restart Level
                </button>
                <button onClick={onBack} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 transition">
                     Quit Game
                </button>
              </div>
          </div>
      )}

      {/* Completion Modal */}
      {isCompleted && (
          <div className="absolute inset-0 bg-blue-600/90 z-50 flex flex-col items-center justify-center text-white animate-fade-in">
              <div className="bg-white text-stone-800 p-8 rounded-2xl shadow-2xl w-80 text-center animate-pop">
                  <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4 text-green-600">
                      <Icons.Check className="w-8 h-8" />
                  </div>
                  <h2 className="text-2xl font-bold mb-2">Solved!</h2>
                  <p className="text-stone-500 mb-6">Excellent work.</p>
                  <p className="text-xl font-medium mb-8">{formatTime(timer)}</p>

                  <button onClick={onBack} className="w-full py-3 bg-stone-800 text-white rounded-xl font-medium hover:bg-stone-700 transition mb-3">
                      Back to Levels
                  </button>
                  {/* Next level logic would go here, simplistic for now */}
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Board, Cell, Difficulty, LevelProgress } from '../types';
import { generateLevel, checkErrors, isGameSolved } from '../utils/sudoku';
import { Storage } from '../utils/storage';
import { Icons } from './ui/Icons';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  onNextLevel: () => void;
  settings: any;
}

export const SudokuGame: React.FC<SudokuGameProps> = ({ 
  difficulty, 
  levelId, 
  onBack, 
  onComplete, 
  onSettingsOpen,
  onNextLevel,
  settings 
}) => {
  const [board, setBoard] = useState<Board>([]);
  const [solvedBoard, setSolvedBoard] = useState<number[][]>([]);
  const [selectedCell, setSelectedCell] = useState<[number, number] | null>(null);
  const [isPencilMode, setIsPencilMode] = useState(false);
  const [history, setHistory] = useState<Board[]>([]);
  const [timer, setTimer] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [loading, setLoading] = useState(true);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);

  const timerRef = useRef<any>(null);

  // Initialize Game Logic
  const initializeGame = useCallback(() => {
    setLoading(true);
    setShowRestartConfirm(false);
    setIsPaused(false);
    setIsCompleted(false);
    setHistory([]);

    const savedProgress = Storage.getLevelProgress(difficulty, levelId);

    // Only load saved progress if we are NOT resetting (handled by checking if savedProgress exists and has state)
    // However, if we just cleared it in restart, this will return undefined or empty status.
    if (savedProgress && savedProgress.status === 'in-progress' && savedProgress.boardState) {
      setBoard(savedProgress.boardState);
      setTimer(savedProgress.timeElapsed);
      const { solved } = generateLevel(difficulty, levelId); 
      setSolvedBoard(solved);
    } else {
      const { initial, solved } = generateLevel(difficulty, levelId);
      setBoard(initial);
      setSolvedBoard(solved);
      setTimer(0);
    }
    setLoading(false);
  }, [difficulty, levelId]);

  useEffect(() => {
    initializeGame();
    return () => stopTimer();
  }, [initializeGame]);

  const handleRestart = () => {
      Storage.clearLevelProgress(difficulty, levelId);
      initializeGame();
  };

  // Timer Logic
  const startTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = setInterval(() => {
      setTimer((t) => t + 1);
    }, 1000);
  };

  const stopTimer = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  useEffect(() => {
    if (!loading && !isPaused && !isCompleted && !showRestartConfirm) {
      startTimer();
    } else {
      stopTimer();
    }
    return () => stopTimer();
  }, [loading, isPaused, isCompleted, showRestartConfirm]);

  // Auto-save
  useEffect(() => {
    if (loading || isCompleted || showRestartConfirm) return;

    const save = setTimeout(() => {
      const progress: LevelProgress = {
        levelId,
        difficulty,
        status: 'in-progress',
        timeElapsed: timer,
        lastPlayed: Date.now(),
        boardState: board,
      };
      Storage.saveLevelProgress(progress);
    }, 1000);

    return () => clearTimeout(save);
  }, [board, timer, difficulty, levelId, loading, isCompleted, showRestartConfirm]);


  const handleCellClick = (row: number, col: number) => {
    if (isPaused || isCompleted) return;
    setSelectedCell([row, col]);
  };

  const handleNumberInput = (num: number) => {
    if (!selectedCell || isPaused || isCompleted) return;
    const [r, c] = selectedCell;
    const currentCell = board[r][c];

    if (currentCell.isFixed) return;

    // Push to history
    setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);

    const newBoard = [...board];
    const newCell = { ...newBoard[r][c] };

    if (isPencilMode) {
      // Toggle note
      if (newCell.notes.includes(num)) {
        newCell.notes = newCell.notes.filter(n => n !== num);
      } else {
        newCell.notes = [...newCell.notes, num].sort();
      }
    } else {
      // Set value
      if (newCell.value === num) {
        newCell.value = null; // Toggle off if same
        newCell.isError = false;
      } else {
        newCell.value = num as any;
        // Check immediate error
        newCell.isError = num !== solvedBoard[r][c];
        newCell.notes = [];
      }
    }

    newBoard[r][c] = newCell;
    setBoard(newBoard);

    // Check Win Condition
    if (!isPencilMode && newCell.value) {
       checkCompletion(newBoard);
    }
  };

  const checkCompletion = (currentBoard: Board) => {
      let filled = 0;
      let correct = 0;
      for(let r=0; r<9; r++) {
          for(let c=0; c<9; c++) {
              if (currentBoard[r][c].value !== null) {
                  filled++;
                  if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
              }
          }
      }

      if (filled === 81 && correct === 81) {
          setIsCompleted(true);
          stopTimer();

          // Save completion
          const progress: LevelProgress = {
            levelId,
            difficulty,
            status: 'completed',
            timeElapsed: timer,
            lastPlayed: Date.now(),
            boardState: undefined, 
          };
          Storage.saveLevelProgress(progress);
      }
  };

  const handleErase = () => {
    if (!selectedCell || isPaused) return;
    const [r, c] = selectedCell;
    if (board[r][c].isFixed) return;

    setHistory(prev => [...prev, JSON.parse(JSON.stringify(board))]);
    const newBoard = [...board];
    newBoard[r][c].value = null;
    newBoard[r][c].notes = [];
    newBoard[r][c].isError = false;
    setBoard(newBoard);
  };

  const handleUndo = () => {
    if (history.length === 0 || isPaused) return;
    const previous = history[history.length - 1];
    setBoard(previous);
    setHistory(prev => prev.slice(0, -1));
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const getCellClass = (cell: Cell, r: number, c: number) => {
    let base = "w-full h-full flex items-center justify-center text-lg sm:text-2xl transition-colors duration-200 cursor-pointer select-none relative ";
    const borderR = (c + 1) % 3 === 0 && c !== 8 ? "border-r-2 border-stone-300" : "border-r border-stone-200";
    const borderB = (r + 1) % 3 === 0 && r !== 8 ? "border-b-2 border-stone-300" : "border-b border-stone-200";
    base += `${borderR} ${borderB} `;

    if (selectedCell) {
        const [sr, sc] = selectedCell;
        const isSelected = sr === r && sc === c;
        const isRelated = sr === r || sc === c || (Math.floor(sr/3) === Math.floor(r/3) && Math.floor(sc/3) === Math.floor(c/3));
        const isSameValue = cell.value !== null && board[sr][sc].value === cell.value;

        if (isSelected) {
            base += "bg-blue-500 text-white ";
        } else if (settings.highlight && isSameValue) {
            base += "bg-blue-200 ";
        } else if (settings.highlight && isRelated) {
            base += "bg-stone-100 ";
        } else {
             base += "bg-white ";
        }
    } else {
        base += "bg-white ";
    }

    if (cell.isError) {
        if (selectedCell && selectedCell[0] === r && selectedCell[1] === c) {
            // keep blue bg
        } else {
            base = base.replace("bg-stone-100", "bg-red-50").replace("bg-white", "bg-red-50");
            base += "text-red-500 ";
        }
    } else if (cell.isFixed) {
        base += "font-semibold text-stone-900 ";
    } else {
        base += "font-medium text-blue-600 ";
    }
    return base;
  };

  if (loading) return <div className="h-full w-full flex items-center justify-center">Loading...</div>;

  return (
    <div className="h-full flex flex-col max-w-lg mx-auto p-4 relative animate-fade-in">
      {/* Header */}
      <div className="flex justify-between items-center mb-6">
        <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition">
          <Icons.Back className="w-6 h-6 text-stone-600" />
        </button>
        <div className="flex flex-col items-center">
            <span className="text-xs font-bold tracking-wider text-stone-400 uppercase">{difficulty}</span>
            <span className="text-xl font-medium tabular-nums text-stone-700">{formatTime(timer)}</span>
        </div>
        <div className="flex gap-1">
            <button onClick={() => setIsPaused(true)} className="p-2 rounded-full hover:bg-stone-200 transition">
                <Icons.Pause className="w-6 h-6 text-stone-600" />
            </button>
            <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200 transition">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>
      </div>

      {/* Board */}
      <div className="aspect-square w-full bg-stone-300 border-2 border-stone-300 rounded-lg overflow-hidden shadow-sm">
        <div className="grid grid-rows-9 h-full">
          {board.map((row, rIndex) => (
            <div key={rIndex} className="grid grid-cols-9 h-full">
              {row.map((cell, cIndex) => (
                <div 
                    key={`${rIndex}-${cIndex}`} 
                    className={getCellClass(cell, rIndex, cIndex)}
                    onClick={() => handleCellClick(rIndex, cIndex)}
                >
                  {cell.value ? (
                      <span>{cell.value}</span>
                  ) : (
                      <div className="grid grid-cols-3 w-full h-full p-0.5">
                          {[1,2,3,4,5,6,7,8,9].map(n => (
                              <div key={n} className="flex items-center justify-center text-[8px] sm:text-[10px] leading-none text-stone-500">
                                  {cell.notes.includes(n) ? n : ''}
                              </div>
                          ))}
                      </div>
                  )}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* Controls */}
      <div className="mt-8 flex flex-col gap-4">
        {/* Actions */}
        <div className="flex justify-between px-4">
            <button onClick={handleUndo} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Undo className="w-5 h-5" /></div>
                <span className="text-xs">Undo</span>
            </button>
            <button onClick={() => setIsPencilMode(!isPencilMode)} className={`flex flex-col items-center gap-1 active:scale-95 transition ${isPencilMode ? 'text-blue-500' : 'text-stone-500'}`}>
                <div className={`p-3 rounded-full shadow-sm border border-stone-100 ${isPencilMode ? 'bg-blue-50 border-blue-200' : 'bg-white'}`}>
                    <Icons.Pencil className="w-5 h-5" />
                    {isPencilMode && <span className="absolute top-0 right-0 w-2 h-2 bg-blue-500 rounded-full"></span>}
                </div>
                <span className="text-xs">Pencil</span>
            </button>
            <button onClick={handleErase} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Erase className="w-5 h-5" /></div>
                <span className="text-xs">Erase</span>
            </button>
             <button className="flex flex-col items-center gap-1 text-stone-300 cursor-not-allowed">
                <div className="p-3 bg-stone-50 rounded-full border border-stone-100"><Icons.Hint className="w-5 h-5" /></div>
                <span className="text-xs">Hint</span>
            </button>
        </div>

        {/* Numpad */}
        <div className="grid grid-cols-9 gap-1 mt-2">
            {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                <button
                    key={num}
                    onClick={() => handleNumberInput(num)}
                    className="aspect-[4/5] flex items-center justify-center text-xl font-medium text-blue-600 bg-white rounded-lg shadow-sm border-b-2 border-stone-100 active:border-b-0 active:translate-y-[2px] transition-all"
                >
                    {num}
                </button>
            ))}
        </div>
      </div>

      {/* Pause Modal */}
      {isPaused && (
          <div className="absolute inset-0 bg-stone-50/90 backdrop-blur-sm z-40 flex flex-col items-center justify-center animate-fade-in">
              <h2 className="text-2xl font-bold text-stone-800 mb-8">Game Paused</h2>
              <div className="flex flex-col gap-4 w-48">
                <button onClick={() => setIsPaused(false)} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white rounded-xl shadow-lg active:scale-95 transition">
                    <Icons.Play className="w-5 h-5" /> Resume
                </button>
                <button 
                    onClick={() => setShowRestartConfirm(true)} 
                    className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 rounded-xl active:scale-95 transition"
                >
                    <Icons.Reset className="w-5 h-5" /> Restart Level
                </button>
                <button onClick={onBack} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 transition">
                     Quit Game
                </button>
              </div>
          </div>
      )}

      {/* Restart Confirmation Modal */}
      {showRestartConfirm && (
          <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/10 backdrop-blur-sm px-4 animate-fade-in">
             <div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                <h3 className="text-lg font-bold text-stone-800 mb-2">Restart Level?</h3>
                <p className="text-stone-500 text-sm mb-6">Are you sure? This will reset all progress on this level.</p>
                <div className="flex gap-3">
                   <button onClick={() => setShowRestartConfirm(false)} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium">Cancel</button>
                   <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md">Restart</button>
                </div>
             </div>
          </div>
      )}

      {/* Completion Modal */}
      {isCompleted && (
          <div className="absolute inset-0 bg-green-500/95 z-50 flex flex-col items-center justify-center text-white animate-fade-in">
              <div className="bg-white text-stone-800 p-8 rounded-2xl shadow-2xl w-80 text-center animate-pop">
                  <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6 text-green-500">
                      <Icons.Check className="w-10 h-10 animate-scale-loop" />
                  </div>
                  <h2 className="text-2xl font-bold mb-2">Solved!</h2>
                  <p className="text-stone-500 mb-6">Excellent work.</p>
                  <p className="text-2xl font-medium mb-8 tabular-nums">{formatTime(timer)}</p>

                  <div className="flex flex-col gap-3">
                    <button onClick={onNextLevel} className="w-full py-3 bg-stone-800 text-white rounded-xl font-medium hover:bg-stone-700 active:scale-95 transition shadow-lg">
                        Play Next Level
                    </button>
                    <button onClick={onBack} className="w-full py-3 bg-white text-stone-600 border border-stone-200 rounded-xl font-medium hover:bg-stone-50 active:scale-95 transition">
                        Back to Menu
                    </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { Icons } from './components/ui/Icons';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings';

interface SettingsModalProps {
    settings: AppSettings;
    onToggle: (key: keyof AppSettings) => void;
    onReset: () => void;
    onClose: () => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ settings, onToggle, onReset, onClose }) => (
    <div className="fixed inset-0 z-[100] bg-black/20 backdrop-blur-sm flex items-end sm:items-center justify-center animate-fade-in" onClick={onClose}>
        <div className="bg-white w-full max-w-md p-6 rounded-t-3xl sm:rounded-3xl shadow-2xl animate-slide-up" onClick={e => e.stopPropagation()}>
            <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-stone-800">Settings</h3>
                <button onClick={onClose} className="p-2 bg-stone-100 rounded-full hover:bg-stone-200"><Icons.Close className="w-5 h-5" /></button>
            </div>

            <div className="space-y-4">
                <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                    <div className="flex items-center gap-3 text-stone-700">
                        <Icons.Sound className="w-5 h-5" />
                        <span>Sound Effects</span>
                    </div>
                    <button onClick={() => onToggle('sound')} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings.sound ? 'bg-green-500' : 'bg-stone-300'}`}>
                        <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings.sound ? 'translate-x-5' : 'translate-x-0'}`}></div>
                    </button>
                </div>
                <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                    <div className="flex items-center gap-3 text-stone-700">
                        <Icons.Eye className="w-5 h-5" />
                        <span>Highlight Areas</span>
                    </div>
                    <button onClick={() => onToggle('highlight')} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings.highlight ? 'bg-green-500' : 'bg-stone-300'}`}>
                        <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings.highlight ? 'translate-x-5' : 'translate-x-0'}`}></div>
                    </button>
                </div>
                {/* More settings can go here */}
            </div>

            <div className="mt-8 pt-6 border-t border-stone-100">
                <button onClick={onReset} className="w-full py-3 flex items-center justify-center gap-2 text-red-500 hover:bg-red-50 rounded-xl transition">
                    <Icons.Trash className="w-5 h-5" /> Reset All Progress
                </button>
            </div>
        </div>
    </div>
);

function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [showSettings, setShowSettings] = useState(false);

  // Splash Screen Effect
  useEffect(() => {
    const timer = setTimeout(() => {
      setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  const handleDifficultySelect = (diff: Difficulty) => {
    setSelectedDifficulty(diff);
    setScreen('levels');
  };

  const handleLevelSelect = (levelId: number) => {
    setSelectedLevel(levelId);
    setScreen('game');
  };

  const handleNextLevel = () => {
      if (selectedLevel && selectedLevel < 30) {
          setSelectedLevel(selectedLevel + 1);
          // SudokuGame will re-mount or re-init because selectedLevel changed
      } else {
          // If level 30, go back to levels
          setScreen('levels');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  // --- Render Components ---

  // 1. Splash
  if (screen === 'splash') {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-stone-50">
        <div className="animate-fade-in flex flex-col items-center">
            <div className="w-20 h-20 bg-stone-800 rounded-2xl mb-6 shadow-xl flex items-center justify-center">
                <div className="grid grid-cols-2 gap-1">
                    <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                    <div className="w-3 h-3 bg-white rounded-sm"></div>
                    <div className="w-3 h-3 bg-white rounded-sm"></div>
                    <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                </div>
            </div>
          <h1 className="text-3xl font-light tracking-widest text-stone-800">MINIMAL</h1>
          <h2 className="text-xl font-bold tracking-widest text-stone-400">SUDOKU</h2>
        </div>
      </div>
    );
  }

  // 2. Difficulty Selection
  if (screen === 'difficulty') {
    const difficulties = Object.values(Difficulty);
    return (
      <div className="min-h-screen bg-paper text-stone-800 p-6 flex flex-col items-center">
        <div className="w-full max-w-md flex justify-between items-center mb-8 mt-4">
            <div>
                <h1 className="text-2xl font-bold">New Game</h1>
                <p className="text-stone-400 text-sm">Select your challenge</p>
            </div>
            <button onClick={() => setShowSettings(true)} className="p-2 bg-white rounded-full shadow-sm hover:shadow-md transition">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>

        <div className="w-full max-w-md grid grid-cols-2 gap-4">
          {difficulties.map((diff) => {
             const completed = Storage.getCompletedCount(diff);
             return (
                <button
                key={diff}
                onClick={() => handleDifficultySelect(diff)}
                className="bg-white p-6 rounded-2xl shadow-sm border border-stone-100 flex flex-col items-start gap-2 hover:border-blue-200 hover:shadow-md transition-all active:scale-95 text-left"
                >
                <span className="text-lg font-semibold text-stone-700">{diff}</span>
                <span className="text-xs text-stone-400 font-medium tracking-wide">{completed} / 30 Solved</span>
                <div className="w-full h-1 bg-stone-100 rounded-full mt-2 overflow-hidden">
                    <div className="h-full bg-stone-800" style={{ width: `${(completed/30)*100}%` }}></div>
                </div>
                </button>
            )
          })}
        </div>
        {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  // 3. Level Selection
  if (screen === 'levels' && selectedDifficulty) {
    const levels = Array.from({ length: 30 }, (_, i) => i + 1);

    return (
      <div className="min-h-screen bg-paper p-6 flex flex-col items-center">
        <div className="w-full max-w-md flex items-center mb-8 mt-4 relative">
            <button onClick={() => setScreen('difficulty')} className="absolute left-0 p-2 rounded-full hover:bg-stone-200">
                <Icons.Back className="w-6 h-6" />
            </button>
            <div className="w-full text-center">
                <h1 className="text-xl font-bold">{selectedDifficulty}</h1>
                <p className="text-xs text-stone-400 uppercase tracking-widest">Select Level</p>
            </div>
             <button onClick={() => setShowSettings(true)} className="absolute right-0 p-2 rounded-full hover:bg-stone-200">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>

        <div className="w-full max-w-md grid grid-cols-5 gap-3">
          {levels.map((lvl) => {
            const progress = Storage.getLevelProgress(selectedDifficulty, lvl);
            const isCompleted = progress?.status === 'completed';
            const isInProgress = progress?.status === 'in-progress';

            return (
              <button
                key={lvl}
                onClick={() => handleLevelSelect(lvl)}
                className={`
                  aspect-square rounded-xl flex flex-col items-center justify-center relative transition-all active:scale-90
                  ${isCompleted 
                    ? 'bg-stone-200 text-stone-400' 
                    : isInProgress 
                        ? 'bg-white border-2 border-blue-400 shadow-md text-stone-800' 
                        : 'bg-white border border-stone-100 shadow-sm hover:shadow-md text-stone-800'}
                `}
              >
                <span className="font-bold text-lg">{lvl}</span>
                {isCompleted && <Icons.Check className="w-4 h-4 absolute bottom-1 text-stone-500" />}
                {isInProgress && <div className="w-1.5 h-1.5 rounded-full bg-blue-500 absolute bottom-2"></div>}
              </button>
            );
          })}
        </div>
        {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  // 4. Game Screen
  if (screen === 'game' && selectedDifficulty && selectedLevel) {
    return (
      <div className="h-screen w-full bg-paper">
         <SudokuGame 
            difficulty={selectedDifficulty}
            levelId={selectedLevel}
            onBack={() => setScreen('levels')}
            onComplete={() => {}} 
            onSettingsOpen={() => setShowSettings(true)}
            onNextLevel={handleNextLevel}
            settings={settings}
         />
         {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  return null;
}

export default App;

import { Difficulty, Board, Cell, CellValue } from '../types';

// Simple seeded random number generator (Linear Congruential Generator)
class SeededRandom {
    seed: number;
    constructor(seed: number) {
        this.seed = seed;
    }

    // Returns a number between 0 and 1
    next(): number {
        this.seed = (this.seed * 9301 + 49297) % 233280;
        return this.seed / 233280;
    }
}

// Helper to check if placing num at board[row][col] is valid (Standard Rules)
export function isValid(board: number[][], row: number, col: number, num: number): boolean {
  for (let i = 0; i < 9; i++) {
    // Check Row
    if (board[row][i] === num && i !== col) return false;
    // Check Column
    if (board[i][col] === num && i !== row) return false;
    // Check 3x3 Box
    const boxRow = 3 * Math.floor(row / 3) + Math.floor(i / 3);
    const boxCol = 3 * Math.floor(col / 3) + (i % 3);
    if (board[boxRow][boxCol] === num && (boxRow !== row || boxCol !== col)) return false;
  }
  return true;
}

// Solves/Generates a board using backtracking with Seeded Random
function solveBoard(board: number[][], rng: SeededRandom): boolean {
  for (let row = 0; row < 9; row++) {
    for (let col = 0; col < 9; col++) {
      if (board[row][col] === 0) {
        // Randomize 1-9 check order using seeded RNG
        const nums = [1, 2, 3, 4, 5, 6, 7, 8, 9]
            .map(value => ({ value, sort: rng.next() }))
            .sort((a, b) => a.sort - b.sort)
            .map(({ value }) => value);

        for (const num of nums) {
          if (isValid(board, row, col, num)) {
            board[row][col] = num;
            if (solveBoard(board, rng)) return true;
            board[row][col] = 0;
          }
        }
        return false;
      }
    }
  }
  return true;
}

// Generate a full solved board based on levelId
function generateFullBoard(levelId: number, difficultySeed: number): number[][] {
    const rng = new SeededRandom(levelId + difficultySeed);
    const board = Array.from({ length: 9 }, () => Array(9).fill(0));
    solveBoard(board, rng);
    return board;
}

function getDifficultySeed(diff: Difficulty): number {
    switch(diff) {
        case Difficulty.SuperEasy: return 1000;
        case Difficulty.Easy: return 2000;
        case Difficulty.Normal: return 3000;
        case Difficulty.Hard: return 4000;
        case Difficulty.Intense: return 5000;
        case Difficulty.Impossible: return 6000;
        default: return 0;
    }
}

export function generateLevel(difficulty: Difficulty, levelId: number): { initial: Board, solved: number[][] } {
    const seedBase = getDifficultySeed(difficulty);
    const solvedRaw = generateFullBoard(levelId, seedBase);

    // Create a new RNG for hole removal so the holes are consistent for this level
    const rng = new SeededRandom(levelId + seedBase + 500);

    // Determine number of holes based on difficulty
    let holes = 30; 
    switch(difficulty) {
        case Difficulty.SuperEasy: holes = 25; break;
        case Difficulty.Easy: holes = 35; break;
        case Difficulty.Normal: holes = 42; break;
        case Difficulty.Hard: holes = 50; break;
        case Difficulty.Intense: holes = 56; break;
        case Difficulty.Impossible: holes = 60; break;
    }

    // Deep copy for puzzle
    const puzzleRaw = solvedRaw.map(r => [...r]);

    // Remove numbers to create holes
    let attempts = holes;
    while (attempts > 0) {
        const r = Math.floor(rng.next() * 9);
        const c = Math.floor(rng.next() * 9);
        if (puzzleRaw[r][c] !== 0) {
            puzzleRaw[r][c] = 0;
            attempts--;
        }
    }

    // Convert to rich Cell objects
    const initial: Board = puzzleRaw.map((row, rIndex) => 
        row.map((val, cIndex) => ({
            row: rIndex,
            col: cIndex,
            value: val === 0 ? null : (val as CellValue),
            isFixed: val !== 0,
            notes: [],
            isError: false
        }))
    );

    return { initial, solved: solvedRaw };
}

export function checkErrors(current: Board, solved: number[][]): Board {
    return current.map(row => 
        row.map(cell => ({
            ...cell,
            isError: cell.value !== null && cell.value !== solved[cell.row][cell.col]
        }))
    );
}

export function isGameSolved(current: Board): boolean {
    for(let r=0; r<9; r++) {
        for(let c=0; c<9; c++) {
            const cell = current[r][c];
            if (cell.value === null || cell.isError) return false;
        }
    }
    return true;
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Board, Cell, Difficulty, LevelProgress } from '../types';
import { generateLevel, isValid, isGameSolved } from '../utils/sudoku';
import { Storage } from '../utils/storage';
import { Icons } from './ui/Icons';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  onNextLevel: () => void;
  settings: any;
}

export const SudokuGame: React.FC<SudokuGameProps> = ({ 
  difficulty, 
  levelId, 
  onBack, 
  onComplete, 
  onSettingsOpen,
  onNextLevel,
  settings 
}) => {
  const [board, setBoard] = useState<Board>([]);
  const [solvedBoard, setSolvedBoard] = useState<number[][]>([]);
  const [selectedCell, setSelectedCell] = useState<[number, number] | null>(null);
  const [isPencilMode, setIsPencilMode] = useState(false);
  const [history, setHistory] = useState<Board[]>([]);
  const [timer, setTimer] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [loading, setLoading] = useState(true);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);

  const timerRef = useRef<any>(null);

  // Initialize Game Logic
  const initializeGame = useCallback(() => {
    setLoading(true);
    setShowRestartConfirm(false);
    setIsPaused(false);
    setIsCompleted(false);
    setHistory([]);

    const savedProgress = Storage.getLevelProgress(difficulty, levelId);

    // We only use saved progress if it's NOT a fresh restart (which clears storage before calling this)
    // The component calls initializeGame on mount.
    if (savedProgress && savedProgress.status === 'in-progress' && savedProgress.boardState) {
      setBoard(savedProgress.boardState);
      setTimer(savedProgress.timeElapsed);
      const { solved } = generateLevel(difficulty, levelId); 
      setSolvedBoard(solved);
    } else {
      // Generate the *Same* level based on ID
      const { initial, solved } = generateLevel(difficulty, levelId);
      setBoard(initial);
      setSolvedBoard(solved);
      setTimer(0);
    }
    setLoading(false);
  }, [difficulty, levelId]);

  useEffect(() => {
    initializeGame();
    return () => stopTimer();
  }, [initializeGame]);

  const handleRestart = () => {
      // Clear storage
      Storage.clearLevelProgress(difficulty, levelId);
      // Re-initialize (which generates same seed)
      initializeGame();
  };

  // Timer Logic
  const startTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = setInterval(() => {
      setTimer((t) => t + 1);
    }, 1000);
  };

  const stopTimer = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  useEffect(() => {
    if (!loading && !isPaused && !isCompleted && !showRestartConfirm) {
      startTimer();
    } else {
      stopTimer();
    }
    return () => stopTimer();
  }, [loading, isPaused, isCompleted, showRestartConfirm]);

  // Auto-save
  useEffect(() => {
    if (loading || isCompleted || showRestartConfirm) return;

    const save = setTimeout(() => {
      const progress: LevelProgress = {
        levelId,
        difficulty,
        status: 'in-progress',
        timeElapsed: timer,
        lastPlayed: Date.now(),
        boardState: board,
      };
      Storage.saveLevelProgress(progress);
    }, 1000);

    return () => clearTimeout(save);
  }, [board, timer, difficulty, levelId, loading, isCompleted, showRestartConfirm]);


  const handleCellClick = (row: number, col: number) => {
    if (isPaused || isCompleted) return;
    setSelectedCell([row, col]);
  };

  const handleNumberInput = (num: number) => {
    if (!selectedCell || isPaused || isCompleted) return;
    const [r, c] = selectedCell;
    const currentCell = board[r][c];

    if (currentCell.isFixed) return;

    // Push to history
    setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);

    const newBoard = [...board];
    const newCell = { ...newBoard[r][c] };

    if (isPencilMode) {
      if (newCell.notes.includes(num)) {
        newCell.notes = newCell.notes.filter(n => n !== num);
      } else {
        newCell.notes = [...newCell.notes, num].sort();
      }
    } else {
      // Set value
      if (newCell.value === num) {
        newCell.value = null; 
        newCell.isError = false;
      } else {
        newCell.value = num as any;
        newCell.notes = [];

        // Error Logic
        const isHarderDifficulty = 
            difficulty === Difficulty.Normal || 
            difficulty === Difficulty.Hard || 
            difficulty === Difficulty.Intense || 
            difficulty === Difficulty.Impossible;

        if (isHarderDifficulty) {
            // Only flag error if it conflicts with an existing number on the board (obvious error)
            // We temporarily check validity on the current board
            // Note: We need a raw number board for the helper
            const rawBoard = newBoard.map(row => row.map(cell => cell.value || 0));
            // Temporarily zero out current cell to check validity of placement
            rawBoard[r][c] = 0; 

            const validMove = isValid(rawBoard, r, c, num);
            newCell.isError = !validMove; 
        } else {
            // Easier difficulties: Check against the solution immediately
            newCell.isError = num !== solvedBoard[r][c];
        }
      }
    }

    newBoard[r][c] = newCell;
    setBoard(newBoard);

    if (!isPencilMode && newCell.value) {
       checkCompletion(newBoard);
    }
  };

  const checkCompletion = (currentBoard: Board) => {
      let filled = 0;
      let correct = 0;
      for(let r=0; r<9; r++) {
          for(let c=0; c<9; c++) {
              if (currentBoard[r][c].value !== null) {
                  filled++;
                  if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
              }
          }
      }

      if (filled === 81 && correct === 81) {
          setIsCompleted(true);
          stopTimer();

          const progress: LevelProgress = {
            levelId,
            difficulty,
            status: 'completed',
            timeElapsed: timer,
            lastPlayed: Date.now(),
            boardState: undefined, 
          };
          Storage.saveLevelProgress(progress);
      }
  };

  const handleErase = () => {
    if (!selectedCell || isPaused) return;
    const [r, c] = selectedCell;
    if (board[r][c].isFixed) return;

    setHistory(prev => [...prev, JSON.parse(JSON.stringify(board))]);
    const newBoard = [...board];
    newBoard[r][c].value = null;
    newBoard[r][c].notes = [];
    newBoard[r][c].isError = false;
    setBoard(newBoard);
  };

  const handleUndo = () => {
    if (history.length === 0 || isPaused) return;
    const previous = history[history.length - 1];
    setBoard(previous);
    setHistory(prev => prev.slice(0, -1));
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const getCellClass = (cell: Cell, r: number, c: number) => {
    let base = "w-full h-full flex items-center justify-center text-lg sm:text-2xl transition-colors duration-200 cursor-pointer select-none relative ";
    const borderR = (c + 1) % 3 === 0 && c !== 8 ? "border-r-2 border-stone-300" : "border-r border-stone-200";
    const borderB = (r + 1) % 3 === 0 && r !== 8 ? "border-b-2 border-stone-300" : "border-b border-stone-200";
    base += `${borderR} ${borderB} `;

    if (selectedCell) {
        const [sr, sc] = selectedCell;
        const isSelected = sr === r && sc === c;
        const isRelated = sr === r || sc === c || (Math.floor(sr/3) === Math.floor(r/3) && Math.floor(sc/3) === Math.floor(c/3));
        const isSameValue = cell.value !== null && board[sr][sc].value === cell.value;

        if (isSelected) {
            base += "bg-blue-400 text-white "; // Lighter blue selection
        } else if (settings.highlight && isSameValue) {
            base += "bg-blue-100 "; // Lighter same-value
        } else if (settings.highlight && isRelated) {
            base += "bg-stone-100 ";
        } else {
             base += "bg-white ";
        }
    } else {
        base += "bg-white ";
    }

    if (cell.isError) {
        if (selectedCell && selectedCell[0] === r && selectedCell[1] === c) {
            // keep blue bg, but maybe indicate error?
        } else {
            base = base.replace("bg-stone-100", "bg-red-50").replace("bg-white", "bg-red-50");
            base += "text-red-500 ";
        }
    } else if (cell.isFixed) {
        base += "font-semibold text-stone-900 ";
    } else {
        base += "font-medium text-blue-600 ";
    }
    return base;
  };

  if (loading) return <div className="h-full w-full flex items-center justify-center">Loading...</div>;

  return (
    <div className="h-full flex flex-col max-w-lg mx-auto p-4 relative animate-fade-in">
      {/* Header */}
      <div className="flex justify-between items-center mb-6 relative">
        <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition z-10">
          <Icons.Back className="w-6 h-6 text-stone-600" />
        </button>

        {/* Centered Title */}
        <div className="absolute left-1/2 -translate-x-1/2 flex flex-col items-center">
            <span className="text-xs font-bold tracking-wider text-stone-400 uppercase text-center w-48">{difficulty} &bull; Level {levelId}</span>
            <span className="text-xl font-medium tabular-nums text-stone-700">{formatTime(timer)}</span>
        </div>

        <div className="flex gap-1 z-10">
            <button onClick={() => setIsPaused(true)} className="p-2 rounded-full hover:bg-stone-200 transition">
                <Icons.Pause className="w-6 h-6 text-stone-600" />
            </button>
            <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200 transition">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>
      </div>

      {/* Board */}
      <div className="aspect-square w-full bg-stone-300 border-2 border-stone-300 rounded-lg overflow-hidden shadow-sm">
        <div className="grid grid-rows-9 h-full">
          {board.map((row, rIndex) => (
            <div key={rIndex} className="grid grid-cols-9 h-full">
              {row.map((cell, cIndex) => (
                <div 
                    key={`${rIndex}-${cIndex}`} 
                    className={getCellClass(cell, rIndex, cIndex)}
                    onClick={() => handleCellClick(rIndex, cIndex)}
                >
                  {cell.value ? (
                      <span>{cell.value}</span>
                  ) : (
                      <div className="grid grid-cols-3 w-full h-full p-0.5">
                          {[1,2,3,4,5,6,7,8,9].map(n => (
                              <div key={n} className="flex items-center justify-center text-[8px] sm:text-[10px] leading-none text-stone-500">
                                  {cell.notes.includes(n) ? n : ''}
                              </div>
                          ))}
                      </div>
                  )}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* Controls */}
      <div className="mt-8 flex flex-col gap-4">
        {/* Actions */}
        <div className="flex justify-between px-4">
            <button onClick={handleUndo} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Undo className="w-5 h-5" /></div>
                <span className="text-xs">Undo</span>
            </button>
            <button onClick={() => setIsPencilMode(!isPencilMode)} className={`flex flex-col items-center gap-1 active:scale-95 transition ${isPencilMode ? 'text-blue-500' : 'text-stone-500'}`}>
                <div className={`p-3 rounded-full shadow-sm border border-stone-100 ${isPencilMode ? 'bg-blue-50 border-blue-200' : 'bg-white'}`}>
                    <Icons.Pencil className="w-5 h-5" />
                    {isPencilMode && <span className="absolute top-0 right-0 w-2 h-2 bg-blue-500 rounded-full"></span>}
                </div>
                <span className="text-xs">Pencil</span>
            </button>
            <button onClick={handleErase} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Erase className="w-5 h-5" /></div>
                <span className="text-xs">Erase</span>
            </button>
             <button className="flex flex-col items-center gap-1 text-stone-300 cursor-not-allowed">
                <div className="p-3 bg-stone-50 rounded-full border border-stone-100"><Icons.Hint className="w-5 h-5" /></div>
                <span className="text-xs">Hint</span>
            </button>
        </div>

        {/* Numpad */}
        <div className="grid grid-cols-9 gap-1 mt-2">
            {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                <button
                    key={num}
                    onClick={() => handleNumberInput(num)}
                    className="aspect-[4/5] flex items-center justify-center text-xl font-medium text-blue-600 bg-white rounded-lg shadow-sm border-b-2 border-stone-100 active:border-b-0 active:translate-y-[2px] transition-all"
                >
                    {num}
                </button>
            ))}
        </div>
      </div>

      {/* Pause Modal */}
      {isPaused && (
          <div className="absolute inset-0 bg-stone-50/90 backdrop-blur-sm z-40 flex flex-col items-center justify-center animate-fade-in">
              <h2 className="text-2xl font-bold text-stone-800 mb-8">Game Paused</h2>
              <div className="flex flex-col gap-4 w-48">
                <button onClick={() => setIsPaused(false)} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                    <Icons.Play className="w-5 h-5" /> Resume
                </button>
                <button 
                    onClick={() => setShowRestartConfirm(true)} 
                    className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 rounded-xl active:scale-95 transition hover:bg-stone-50"
                >
                    <Icons.Reset className="w-5 h-5" /> Restart Level
                </button>
                <button onClick={onBack} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 transition">
                     Quit Game
                </button>
              </div>
          </div>
      )}

      {/* Restart Confirmation Modal */}
      {showRestartConfirm && (
          <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/10 backdrop-blur-sm px-4 animate-fade-in">
             <div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                <h3 className="text-lg font-bold text-stone-800 mb-2">Restart Level?</h3>
                <p className="text-stone-500 text-sm mb-6">Are you sure? This will reset all progress on this level.</p>
                <div className="flex gap-3">
                   <button onClick={() => setShowRestartConfirm(false)} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium active:scale-95 transition">Cancel</button>
                   <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                </div>
             </div>
          </div>
      )}

      {/* Completion Modal */}
      {isCompleted && (
          <div className="absolute inset-0 bg-green-500/50 backdrop-blur-sm z-50 flex flex-col items-center justify-center text-white animate-fade-in">
              <div className="bg-white text-stone-800 p-8 rounded-2xl shadow-2xl w-80 text-center animate-pop">
                  <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6 text-green-500">
                      <Icons.Check className="w-10 h-10 animate-scale-loop" />
                  </div>
                  <h2 className="text-2xl font-bold mb-2">Solved!</h2>
                  <p className="text-stone-500 mb-2 text-sm">Finished in</p>
                  <p className="text-3xl font-medium mb-8 tabular-nums">{formatTime(timer)}</p>

                  <div className="flex flex-col gap-3">
                    <button onClick={onNextLevel} className="w-full py-3 bg-stone-800 text-white rounded-xl font-medium hover:bg-stone-700 active:scale-95 transition shadow-lg active:opacity-80">
                        Play Next Level
                    </button>
                    <button onClick={onBack} className="w-full py-3 bg-white text-stone-600 border border-stone-200 rounded-xl font-medium hover:bg-stone-50 active:scale-95 transition active:opacity-80">
                        Back to Menu
                    </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { Icons } from './components/ui/Icons';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings';

interface SettingsModalProps {
    settings: AppSettings;
    onToggle: (key: keyof AppSettings) => void;
    onReset: () => void;
    onClose: () => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ settings, onToggle, onReset, onClose }) => {
    const [isClosing, setIsClosing] = useState(false);

    const handleClose = () => {
        setIsClosing(true);
        setTimeout(() => {
            onClose();
        }, 300); // Match animation duration
    };

    return (
        <div className={`fixed inset-0 z-[100] bg-black/20 backdrop-blur-sm flex items-end sm:items-center justify-center ${isClosing ? 'animate-fade-out' : 'animate-fade-in'}`} onClick={handleClose}>
            <div 
                className={`bg-white w-full max-w-md p-6 rounded-t-3xl sm:rounded-3xl shadow-2xl ${isClosing ? 'animate-slide-down' : 'animate-slide-up'}`} 
                onClick={e => e.stopPropagation()}
            >
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold text-stone-800">Settings</h3>
                    <button onClick={handleClose} className="p-2 bg-stone-100 rounded-full hover:bg-stone-200"><Icons.Close className="w-5 h-5" /></button>
                </div>

                <div className="space-y-4">
                    <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                        <div className="flex items-center gap-3 text-stone-700">
                            <Icons.Sound className="w-5 h-5" />
                            <span>Sound Effects</span>
                        </div>
                        <button onClick={() => onToggle('sound')} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings.sound ? 'bg-green-500' : 'bg-stone-300'}`}>
                            <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings.sound ? 'translate-x-5' : 'translate-x-0'}`}></div>
                        </button>
                    </div>
                    <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                        <div className="flex items-center gap-3 text-stone-700">
                            <Icons.Eye className="w-5 h-5" />
                            <span>Highlight Areas</span>
                        </div>
                        <button onClick={() => onToggle('highlight')} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings.highlight ? 'bg-green-500' : 'bg-stone-300'}`}>
                            <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings.highlight ? 'translate-x-5' : 'translate-x-0'}`}></div>
                        </button>
                    </div>
                    {/* More settings can go here */}
                </div>

                <div className="mt-8 pt-6 border-t border-stone-100">
                    <button onClick={onReset} className="w-full py-3 flex items-center justify-center gap-2 text-red-500 hover:bg-red-50 rounded-xl transition">
                        <Icons.Trash className="w-5 h-5" /> Reset All Progress
                    </button>
                </div>
            </div>
        </div>
    );
};

function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);

  // Splash Screen Effect
  useEffect(() => {
    const timer = setTimeout(() => {
      setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  const handleDifficultySelect = (diff: Difficulty) => {
    setSelectedDifficulty(diff);
    setScreen('levels');
  };

  const handleLevelSelect = (levelId: number) => {
    // Check if level is completed
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        setReplayLevelId(levelId);
    } else {
        setSelectedLevel(levelId);
        setScreen('game');
    }
  };

  const confirmReplay = () => {
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setSelectedLevel(replayLevelId);
          setReplayLevelId(null);
          setScreen('game');
      }
  };

  const handleNextLevel = () => {
      if (selectedLevel && selectedLevel < 30) {
          setSelectedLevel(selectedLevel + 1);
      } else {
          setScreen('levels');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  // --- Render Components ---

  // 1. Splash
  if (screen === 'splash') {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-stone-50">
        <div className="animate-fade-in flex flex-col items-center">
            <div className="w-20 h-20 bg-stone-800 rounded-2xl mb-6 shadow-xl flex items-center justify-center">
                <div className="grid grid-cols-2 gap-1">
                    <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                    <div className="w-3 h-3 bg-white rounded-sm"></div>
                    <div className="w-3 h-3 bg-white rounded-sm"></div>
                    <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                </div>
            </div>
          <h1 className="text-3xl font-light tracking-widest text-stone-800">MINIMAL</h1>
          <h2 className="text-xl font-bold tracking-widest text-stone-400">SUDOKU</h2>
        </div>
      </div>
    );
  }

  // 2. Difficulty Selection
  if (screen === 'difficulty') {
    const difficulties = Object.values(Difficulty);
    return (
      <div className="min-h-screen bg-paper text-stone-800 p-6 flex flex-col items-center">
        <div className="w-full max-w-md flex justify-between items-center mb-8 mt-4">
            <div>
                <h1 className="text-2xl font-bold">New Game</h1>
                <p className="text-stone-400 text-sm">Select your challenge</p>
            </div>
            <button onClick={() => setShowSettings(true)} className="p-2 bg-white rounded-full shadow-sm hover:shadow-md transition">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>

        <div className="w-full max-w-md grid grid-cols-2 gap-4">
          {difficulties.map((diff) => {
             const completed = Storage.getCompletedCount(diff);
             return (
                <button
                key={diff}
                onClick={() => handleDifficultySelect(diff)}
                className="bg-white p-6 rounded-2xl shadow-sm border border-stone-100 flex flex-col items-start gap-2 hover:border-blue-200 hover:shadow-md transition-all active:scale-95 text-left"
                >
                <span className="text-lg font-semibold text-stone-700">{diff}</span>
                <span className="text-xs text-stone-400 font-medium tracking-wide">{completed} / 30 Solved</span>
                <div className="w-full h-1 bg-stone-100 rounded-full mt-2 overflow-hidden">
                    <div className="h-full bg-stone-800" style={{ width: `${(completed/30)*100}%` }}></div>
                </div>
                </button>
            )
          })}
        </div>
        {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  // 3. Level Selection
  if (screen === 'levels' && selectedDifficulty) {
    const levels = Array.from({ length: 30 }, (_, i) => i + 1);

    return (
      <div className="min-h-screen bg-paper p-6 flex flex-col items-center">
        <div className="w-full max-w-md flex items-center mb-8 mt-4 relative">
            <button onClick={() => setScreen('difficulty')} className="absolute left-0 p-2 rounded-full hover:bg-stone-200">
                <Icons.Back className="w-6 h-6" />
            </button>
            <div className="w-full text-center">
                <h1 className="text-xl font-bold">{selectedDifficulty}</h1>
                <p className="text-xs text-stone-400 uppercase tracking-widest">Select Level</p>
            </div>
             <button onClick={() => setShowSettings(true)} className="absolute right-0 p-2 rounded-full hover:bg-stone-200">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>

        <div className="w-full max-w-md grid grid-cols-5 gap-3">
          {levels.map((lvl) => {
            const progress = Storage.getLevelProgress(selectedDifficulty, lvl);
            const isCompleted = progress?.status === 'completed';
            const isInProgress = progress?.status === 'in-progress';

            return (
              <button
                key={lvl}
                onClick={() => handleLevelSelect(lvl)}
                className={`
                  aspect-square rounded-xl flex flex-col items-center justify-center relative transition-all active:scale-90
                  ${isCompleted 
                    ? 'bg-stone-100 text-stone-300 border border-stone-100' // Greyed out for completed
                    : isInProgress 
                        ? 'bg-white border-2 border-blue-400 shadow-md text-stone-800' 
                        : 'bg-white border border-stone-100 shadow-sm hover:shadow-md text-stone-800'}
                `}
              >
                <span className="font-bold text-lg">{lvl}</span>
                {isInProgress && <div className="w-1.5 h-1.5 rounded-full bg-blue-500 absolute bottom-2"></div>}
              </button>
            );
          })}
        </div>

        {/* Replay Confirmation Modal */}
        {replayLevelId && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/10 backdrop-blur-sm px-4 animate-fade-in">
                <div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                    <h3 className="text-lg font-bold text-stone-800 mb-2">Replay Level {replayLevelId}?</h3>
                    <p className="text-stone-500 text-sm mb-6">This will reset your progress on this level.</p>
                    <div className="flex gap-3">
                        <button onClick={() => setReplayLevelId(null)} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium active:scale-95 transition">Cancel</button>
                        <button onClick={confirmReplay} className="flex-1 py-3 text-white bg-blue-500 rounded-xl font-medium shadow-md active:scale-95 transition">Replay</button>
                    </div>
                </div>
            </div>
        )}

        {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  // 4. Game Screen
  if (screen === 'game' && selectedDifficulty && selectedLevel) {
    return (
      <div className="h-screen w-full bg-paper">
         <SudokuGame 
            difficulty={selectedDifficulty}
            levelId={selectedLevel}
            onBack={() => setScreen('levels')}
            onComplete={() => {}} 
            onSettingsOpen={() => setShowSettings(true)}
            onNextLevel={handleNextLevel}
            settings={settings}
         />
         {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  return null;
}

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Board, Cell, Difficulty, LevelProgress } from '../types';
import { generateLevel, isValid, isGameSolved } from '../utils/sudoku';
import { Storage } from '../utils/storage';
import { Icons } from './ui/Icons';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  onNextLevel: () => void;
  settings: any;
}

export const SudokuGame: React.FC<SudokuGameProps> = ({ 
  difficulty, 
  levelId, 
  onBack, 
  onComplete, 
  onSettingsOpen,
  onNextLevel,
  settings 
}) => {
  const [board, setBoard] = useState<Board>([]);
  const [solvedBoard, setSolvedBoard] = useState<number[][]>([]);
  const [selectedCell, setSelectedCell] = useState<[number, number] | null>(null);
  const [isPencilMode, setIsPencilMode] = useState(false);
  const [history, setHistory] = useState<Board[]>([]);
  const [timer, setTimer] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [loading, setLoading] = useState(true);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);

  // Transition states for pause menu interactions
  const [isResuming, setIsResuming] = useState(false);
  const [isRestarting, setIsRestarting] = useState(false);
  const [isQuitting, setIsQuitting] = useState(false);

  const timerRef = useRef<any>(null);

  // Initialize Game Logic
  const initializeGame = useCallback(() => {
    setLoading(true);
    setShowRestartConfirm(false);
    setIsPaused(false);
    setIsCompleted(false);
    setIsResuming(false);
    setIsRestarting(false);
    setIsQuitting(false);
    setHistory([]);

    const savedProgress = Storage.getLevelProgress(difficulty, levelId);

    if (savedProgress && savedProgress.status === 'in-progress' && savedProgress.boardState) {
      setBoard(savedProgress.boardState);
      setTimer(savedProgress.timeElapsed);
      const { solved } = generateLevel(difficulty, levelId); 
      setSolvedBoard(solved);
    } else {
      const { initial, solved } = generateLevel(difficulty, levelId);
      setBoard(initial);
      setSolvedBoard(solved);
      setTimer(0);
    }
    setLoading(false);
  }, [difficulty, levelId]);

  useEffect(() => {
    initializeGame();
    return () => stopTimer();
  }, [initializeGame]);

  const handleRestart = () => {
      setIsRestarting(true);
      setTimeout(() => {
        Storage.clearLevelProgress(difficulty, levelId);
        initializeGame();
      }, 300);
  };

  const handleResume = () => {
      setIsResuming(true);
      setTimeout(() => {
          setIsPaused(false);
          setIsResuming(false);
      }, 300);
  };

  const handleQuit = () => {
      setIsQuitting(true);
      setTimeout(() => {
          onBack();
      }, 300);
  };

  const handleNextLevelWithAnim = () => {
      setIsQuitting(true); // Re-use quitting anim style for fading out
      setTimeout(() => {
          onNextLevel();
      }, 300);
  };

  // Timer Logic
  const startTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = setInterval(() => {
      setTimer((t) => t + 1);
    }, 1000);
  };

  const stopTimer = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  useEffect(() => {
    if (!loading && !isPaused && !isCompleted && !showRestartConfirm) {
      startTimer();
    } else {
      stopTimer();
    }
    return () => stopTimer();
  }, [loading, isPaused, isCompleted, showRestartConfirm]);

  // Auto-save
  useEffect(() => {
    if (loading || isCompleted || showRestartConfirm) return;

    const save = setTimeout(() => {
      const progress: LevelProgress = {
        levelId,
        difficulty,
        status: 'in-progress',
        timeElapsed: timer,
        lastPlayed: Date.now(),
        boardState: board,
      };
      Storage.saveLevelProgress(progress);
    }, 1000);

    return () => clearTimeout(save);
  }, [board, timer, difficulty, levelId, loading, isCompleted, showRestartConfirm]);


  const handleCellClick = (row: number, col: number) => {
    if (isPaused || isCompleted) return;
    setSelectedCell([row, col]);
  };

  const handleNumberInput = (num: number) => {
    if (!selectedCell || isPaused || isCompleted) return;
    const [r, c] = selectedCell;
    const currentCell = board[r][c];

    if (currentCell.isFixed) return;

    // Push to history
    setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);

    const newBoard = [...board];
    const newCell = { ...newBoard[r][c] };

    if (isPencilMode) {
      if (newCell.notes.includes(num)) {
        newCell.notes = newCell.notes.filter(n => n !== num);
      } else {
        newCell.notes = [...newCell.notes, num].sort();
      }
    } else {
      // Set value
      if (newCell.value === num) {
        newCell.value = null; 
        newCell.isError = false;
      } else {
        newCell.value = num as any;
        newCell.notes = [];

        // Error Logic
        const isHarderDifficulty = 
            difficulty === Difficulty.Normal || 
            difficulty === Difficulty.Hard || 
            difficulty === Difficulty.Intense || 
            difficulty === Difficulty.Impossible;

        if (isHarderDifficulty) {
            // Obvious error check: valid placement in current board state
            const rawBoard = newBoard.map(row => row.map(cell => cell.value || 0));
            rawBoard[r][c] = 0; // Temp clear to check validity
            const validMove = isValid(rawBoard, r, c, num);
            newCell.isError = !validMove; 
        } else {
            // Easy check against solution
            newCell.isError = num !== solvedBoard[r][c];
        }
      }
    }

    newBoard[r][c] = newCell;
    setBoard(newBoard);

    if (!isPencilMode && newCell.value) {
       checkCompletion(newBoard);
    }
  };

  const checkCompletion = (currentBoard: Board) => {
      let filled = 0;
      let correct = 0;
      for(let r=0; r<9; r++) {
          for(let c=0; c<9; c++) {
              if (currentBoard[r][c].value !== null) {
                  filled++;
                  if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
              }
          }
      }

      if (filled === 81 && correct === 81) {
          setIsCompleted(true);
          stopTimer();

          const progress: LevelProgress = {
            levelId,
            difficulty,
            status: 'completed',
            timeElapsed: timer,
            lastPlayed: Date.now(),
            boardState: undefined, 
          };
          Storage.saveLevelProgress(progress);
      }
  };

  const handleErase = () => {
    if (!selectedCell || isPaused) return;
    const [r, c] = selectedCell;
    if (board[r][c].isFixed) return;

    setHistory(prev => [...prev, JSON.parse(JSON.stringify(board))]);
    const newBoard = [...board];
    newBoard[r][c].value = null;
    newBoard[r][c].notes = [];
    newBoard[r][c].isError = false;
    setBoard(newBoard);
  };

  const handleUndo = () => {
    if (history.length === 0 || isPaused) return;
    const previous = history[history.length - 1];
    setBoard(previous);
    setHistory(prev => prev.slice(0, -1));
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const getCellClass = (cell: Cell, r: number, c: number) => {
    let base = "w-full h-full flex items-center justify-center text-lg sm:text-2xl transition-colors duration-200 cursor-pointer select-none relative ";
    const borderR = (c + 1) % 3 === 0 && c !== 8 ? "border-r-2 border-stone-300" : "border-r border-stone-200";
    const borderB = (r + 1) % 3 === 0 && r !== 8 ? "border-b-2 border-stone-300" : "border-b border-stone-200";
    base += `${borderR} ${borderB} `;

    // Conflict Check Logic
    let isConflict = false;
    if (selectedCell && board[selectedCell[0]][selectedCell[1]].isError && board[selectedCell[0]][selectedCell[1]].value !== null) {
        const [sr, sc] = selectedCell;
        const selectedVal = board[sr][sc].value;
        // If current cell has same value as selected cell (which is an error)
        if (cell.value === selectedVal) {
             // Check if it's in the same row, col, or box
             const inRow = r === sr;
             const inCol = c === sc;
             const inBox = Math.floor(r/3) === Math.floor(sr/3) && Math.floor(c/3) === Math.floor(sc/3);

             if (inRow || inCol || inBox) {
                 isConflict = true;
             }
        }
    }

    if (selectedCell) {
        const [sr, sc] = selectedCell;
        const isSelected = sr === r && sc === c;
        const isRelated = sr === r || sc === c || (Math.floor(sr/3) === Math.floor(r/3) && Math.floor(sc/3) === Math.floor(c/3));
        const isSameValue = cell.value !== null && board[sr][sc].value === cell.value;

        if (isSelected) {
            base += "bg-blue-300 text-white "; // Lighter blue selection
        } else if (settings.highlight && isSameValue) {
            base += "bg-blue-100 "; // Lighter same-value
        } else if (settings.highlight && isRelated) {
            base += "bg-stone-100 ";
        } else {
             base += "bg-white ";
        }
    } else {
        base += "bg-white ";
    }

    if (cell.isError || isConflict) {
        if (selectedCell && selectedCell[0] === r && selectedCell[1] === c) {
            // Keep blue background for selected, but maybe text color
        } else {
             // Red background for errors/conflicts
             base = base.replace(/bg-\w+-\d+/, "bg-red-50");
        }
        base += "text-red-500 ";
    } else if (cell.isFixed) {
        base += "font-semibold text-stone-900 ";
    } else {
        base += "font-medium text-blue-600 ";
    }
    return base;
  };

  if (loading) return <div className="h-full w-full flex items-center justify-center">Loading...</div>;

  return (
    <div className={`h-full flex flex-col max-w-lg mx-auto p-4 relative ${isQuitting ? 'animate-fade-out' : 'animate-fade-in'}`}>
      {/* Header */}
      <div className="flex justify-between items-center mb-6 relative">
        <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition z-10">
          <Icons.Back className="w-6 h-6 text-stone-600" />
        </button>

        {/* Centered Title */}
        <div className="absolute left-1/2 -translate-x-1/2 flex flex-col items-center">
            <span className="text-xs font-bold tracking-wider text-stone-400 uppercase text-center w-48">{difficulty} &bull; Level {levelId}</span>
            <span className="text-xl font-medium tabular-nums text-stone-700">{formatTime(timer)}</span>
        </div>

        <div className="flex gap-1 z-10">
            <button onClick={() => setIsPaused(true)} className="p-2 rounded-full hover:bg-stone-200 transition">
                <Icons.Pause className="w-6 h-6 text-stone-600" />
            </button>
            <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200 transition">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>
      </div>

      {/* Board */}
      <div className="aspect-square w-full bg-stone-300 border-2 border-stone-300 rounded-lg overflow-hidden shadow-sm">
        <div className="grid grid-rows-9 h-full">
          {board.map((row, rIndex) => (
            <div key={rIndex} className="grid grid-cols-9 h-full">
              {row.map((cell, cIndex) => (
                <div 
                    key={`${rIndex}-${cIndex}`} 
                    className={getCellClass(cell, rIndex, cIndex)}
                    onClick={() => handleCellClick(rIndex, cIndex)}
                >
                  {cell.value ? (
                      <span>{cell.value}</span>
                  ) : (
                      <div className="grid grid-cols-3 w-full h-full p-0.5">
                          {[1,2,3,4,5,6,7,8,9].map(n => (
                              <div key={n} className="flex items-center justify-center text-[8px] sm:text-[10px] leading-none text-stone-500">
                                  {cell.notes.includes(n) ? n : ''}
                              </div>
                          ))}
                      </div>
                  )}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* Controls */}
      <div className="mt-8 flex flex-col gap-4">
        {/* Actions */}
        <div className="flex justify-between px-4">
            <button onClick={handleUndo} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Undo className="w-5 h-5" /></div>
                <span className="text-xs">Undo</span>
            </button>
            <button onClick={() => setIsPencilMode(!isPencilMode)} className={`flex flex-col items-center gap-1 active:scale-95 transition ${isPencilMode ? 'text-blue-500' : 'text-stone-500'}`}>
                <div className={`p-3 rounded-full shadow-sm border border-stone-100 ${isPencilMode ? 'bg-blue-50 border-blue-200' : 'bg-white'}`}>
                    <Icons.Pencil className="w-5 h-5" />
                    {isPencilMode && <span className="absolute top-0 right-0 w-2 h-2 bg-blue-500 rounded-full"></span>}
                </div>
                <span className="text-xs">Pencil</span>
            </button>
            <button onClick={handleErase} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Erase className="w-5 h-5" /></div>
                <span className="text-xs">Erase</span>
            </button>
             <button className="flex flex-col items-center gap-1 text-stone-300 cursor-not-allowed">
                <div className="p-3 bg-stone-50 rounded-full border border-stone-100"><Icons.Hint className="w-5 h-5" /></div>
                <span className="text-xs">Hint</span>
            </button>
        </div>

        {/* Numpad */}
        <div className="grid grid-cols-9 gap-1 mt-2">
            {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                <button
                    key={num}
                    onClick={() => handleNumberInput(num)}
                    className="aspect-[4/5] flex items-center justify-center text-xl font-medium text-blue-600 bg-white rounded-lg shadow-sm border-b-2 border-stone-100 active:border-b-0 active:translate-y-[2px] transition-all"
                >
                    {num}
                </button>
            ))}
        </div>
      </div>

      {/* Pause Modal */}
      {isPaused && (
          <div className={`absolute inset-0 bg-stone-50/90 backdrop-blur-sm z-40 flex flex-col items-center justify-center ${isResuming ? 'animate-fade-out' : 'animate-fade-in'}`}>
              <h2 className="text-2xl font-bold text-stone-800 mb-8">Game Paused</h2>
              <div className="flex flex-col gap-4 w-48">
                <button onClick={handleResume} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                    <Icons.Play className="w-5 h-5" /> Resume
                </button>
                <button 
                    onClick={() => setShowRestartConfirm(true)} 
                    className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 rounded-xl active:scale-95 transition hover:bg-stone-50"
                >
                    <Icons.Reset className="w-5 h-5" /> Restart Level
                </button>
                <button onClick={handleQuit} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 transition">
                     Quit Game
                </button>
              </div>
          </div>
      )}

      {/* Restart Confirmation Modal */}
      {showRestartConfirm && (
          <div className={`absolute inset-0 z-50 flex items-center justify-center bg-black/10 backdrop-blur-sm px-4 ${isRestarting ? 'animate-fade-out' : 'animate-fade-in'}`}>
             <div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                <h3 className="text-lg font-bold text-stone-800 mb-2">Restart Level?</h3>
                <p className="text-stone-500 text-sm mb-6">Are you sure? This will reset all progress on this level.</p>
                <div className="flex gap-3">
                   <button onClick={() => setShowRestartConfirm(false)} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium active:scale-95 transition">Cancel</button>
                   <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                </div>
             </div>
          </div>
      )}

      {/* Completion Modal */}
      {isCompleted && (
          <div className="absolute inset-0 bg-green-500/50 backdrop-blur-sm z-50 flex flex-col items-center justify-center text-white animate-fade-in">
              <div className="bg-white text-stone-800 p-8 rounded-2xl shadow-2xl w-80 text-center animate-pop">
                  <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6 text-green-500">
                      <Icons.Check className="w-10 h-10 animate-scale-loop" />
                  </div>
                  <h2 className="text-2xl font-bold mb-2">Solved!</h2>
                  <p className="text-stone-500 mb-2 text-sm">Finished in</p>
                  <p className="text-3xl font-medium mb-8 tabular-nums">{formatTime(timer)}</p>

                  <div className="flex flex-col gap-3">
                    <button onClick={handleNextLevelWithAnim} className="w-full py-3 bg-stone-800 text-white rounded-xl font-medium hover:bg-stone-700 active:scale-95 transition shadow-lg active:opacity-80">
                        Play Next Level
                    </button>
                    <button onClick={handleQuit} className="w-full py-3 bg-white text-stone-600 border border-stone-200 rounded-xl font-medium hover:bg-stone-50 active:scale-95 transition active:opacity-80">
                        Back to Menu
                    </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { Icons } from './components/ui/Icons';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings';

interface SettingsModalProps {
    settings: AppSettings;
    onToggle: (key: keyof AppSettings) => void;
    onReset: () => void;
    onClose: () => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ settings, onToggle, onReset, onClose }) => {
    const [isClosing, setIsClosing] = useState(false);

    const handleClose = () => {
        setIsClosing(true);
        setTimeout(() => {
            onClose();
        }, 300); // Match animation duration
    };

    return (
        <div className={`fixed inset-0 z-[100] bg-black/20 backdrop-blur-sm flex items-end sm:items-center justify-center ${isClosing ? 'animate-fade-out' : 'animate-fade-in'}`} onClick={handleClose}>
            <div 
                className={`bg-white w-full max-w-md p-6 rounded-t-3xl sm:rounded-3xl shadow-2xl ${isClosing ? 'animate-slide-down' : 'animate-slide-up'}`} 
                onClick={e => e.stopPropagation()}
            >
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold text-stone-800">Settings</h3>
                    <button onClick={handleClose} className="p-2 bg-stone-100 rounded-full hover:bg-stone-200"><Icons.Close className="w-5 h-5" /></button>
                </div>

                <div className="space-y-4">
                    <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                        <div className="flex items-center gap-3 text-stone-700">
                            <Icons.Sound className="w-5 h-5" />
                            <span>Sound Effects</span>
                        </div>
                        <button onClick={() => onToggle('sound')} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings.sound ? 'bg-green-500' : 'bg-stone-300'}`}>
                            <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings.sound ? 'translate-x-5' : 'translate-x-0'}`}></div>
                        </button>
                    </div>
                    <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                        <div className="flex items-center gap-3 text-stone-700">
                            <Icons.Eye className="w-5 h-5" />
                            <span>Highlight Areas</span>
                        </div>
                        <button onClick={() => onToggle('highlight')} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings.highlight ? 'bg-green-500' : 'bg-stone-300'}`}>
                            <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings.highlight ? 'translate-x-5' : 'translate-x-0'}`}></div>
                        </button>
                    </div>
                    {/* More settings can go here */}
                </div>

                <div className="mt-8 pt-6 border-t border-stone-100">
                    <button onClick={onReset} className="w-full py-3 flex items-center justify-center gap-2 text-red-500 hover:bg-red-50 rounded-xl transition">
                        <Icons.Trash className="w-5 h-5" /> Reset All Progress
                    </button>
                </div>
            </div>
        </div>
    );
};

function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);

  // Transition State
  const [isTransitioning, setIsTransitioning] = useState(false);

  // Splash Screen Effect
  useEffect(() => {
    const timer = setTimeout(() => {
      setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  const handleDifficultySelect = (diff: Difficulty) => {
    setIsTransitioning(true);
    setTimeout(() => {
        setSelectedDifficulty(diff);
        setScreen('levels');
        setIsTransitioning(false);
    }, 300);
  };

  const handleLevelSelect = (levelId: number) => {
    // Check if level is completed
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        setReplayLevelId(levelId);
    } else {
        setIsTransitioning(true);
        setTimeout(() => {
            setSelectedLevel(levelId);
            setScreen('game');
            setIsTransitioning(false);
        }, 300);
    }
  };

  const confirmReplay = () => {
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setIsTransitioning(true);
          setReplayLevelId(null);
          setTimeout(() => {
             setSelectedLevel(replayLevelId);
             setScreen('game');
             setIsTransitioning(false);
          }, 300);
      }
  };

  const handleNextLevel = () => {
      if (selectedLevel && selectedLevel < 30) {
          setSelectedLevel(selectedLevel + 1);
      } else {
          setScreen('levels');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  // --- Render Components ---

  // 1. Splash
  if (screen === 'splash') {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-stone-50">
        <div className="animate-fade-in flex flex-col items-center">
            <div className="w-20 h-20 bg-stone-800 rounded-2xl mb-6 shadow-xl flex items-center justify-center">
                <div className="grid grid-cols-2 gap-1">
                    <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                    <div className="w-3 h-3 bg-white rounded-sm"></div>
                    <div className="w-3 h-3 bg-white rounded-sm"></div>
                    <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                </div>
            </div>
          <h1 className="text-3xl font-light tracking-widest text-stone-800">MINIMAL</h1>
          <h2 className="text-xl font-bold tracking-widest text-stone-400">SUDOKU</h2>
        </div>
      </div>
    );
  }

  // 2. Difficulty Selection
  if (screen === 'difficulty') {
    const difficulties = Object.values(Difficulty);
    return (
      <div className={`min-h-screen bg-paper text-stone-800 p-6 flex flex-col items-center ${isTransitioning ? 'animate-fade-out' : 'animate-fade-in'}`}>
        <div className="w-full max-w-md flex justify-between items-center mb-8 mt-4">
            <div>
                <h1 className="text-2xl font-bold">New Game</h1>
                <p className="text-stone-400 text-sm">Select your challenge</p>
            </div>
            <button onClick={() => setShowSettings(true)} className="p-2 bg-white rounded-full shadow-sm hover:shadow-md transition">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>

        <div className="w-full max-w-md grid grid-cols-2 gap-4">
          {difficulties.map((diff) => {
             const completed = Storage.getCompletedCount(diff);
             return (
                <button
                key={diff}
                onClick={() => handleDifficultySelect(diff)}
                className="bg-white p-6 rounded-2xl shadow-sm border border-stone-100 flex flex-col items-start gap-2 hover:border-blue-200 hover:shadow-md transition-all active:scale-95 text-left"
                >
                <span className="text-lg font-semibold text-stone-700">{diff}</span>
                <span className="text-xs text-stone-400 font-medium tracking-wide">{completed} / 30 Solved</span>
                <div className="w-full h-1 bg-stone-100 rounded-full mt-2 overflow-hidden">
                    <div className="h-full bg-stone-800" style={{ width: `${(completed/30)*100}%` }}></div>
                </div>
                </button>
            )
          })}
        </div>
        {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  // 3. Level Selection
  if (screen === 'levels' && selectedDifficulty) {
    const levels = Array.from({ length: 30 }, (_, i) => i + 1);

    return (
      <div className={`min-h-screen bg-paper p-6 flex flex-col items-center ${isTransitioning ? 'animate-fade-out' : 'animate-fade-in'}`}>
        <div className="w-full max-w-md flex items-center mb-8 mt-4 relative">
            <button onClick={() => setScreen('difficulty')} className="absolute left-0 p-2 rounded-full hover:bg-stone-200">
                <Icons.Back className="w-6 h-6" />
            </button>
            <div className="w-full text-center">
                <h1 className="text-xl font-bold">{selectedDifficulty}</h1>
                <p className="text-xs text-stone-400 uppercase tracking-widest">Select Level</p>
            </div>
             <button onClick={() => setShowSettings(true)} className="absolute right-0 p-2 rounded-full hover:bg-stone-200">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>

        <div className="w-full max-w-md grid grid-cols-5 gap-3">
          {levels.map((lvl) => {
            const progress = Storage.getLevelProgress(selectedDifficulty, lvl);
            const isCompleted = progress?.status === 'completed';
            const isInProgress = progress?.status === 'in-progress';

            return (
              <button
                key={lvl}
                onClick={() => handleLevelSelect(lvl)}
                className={`
                  aspect-square rounded-xl flex flex-col items-center justify-center relative transition-all active:scale-90
                  ${isCompleted 
                    ? 'bg-stone-100 text-stone-300 border border-stone-100' // Greyed out for completed
                    : isInProgress 
                        ? 'bg-white border-2 border-blue-400 shadow-md text-stone-800' 
                        : 'bg-white border border-stone-100 shadow-sm hover:shadow-md text-stone-800'}
                `}
              >
                <span className="font-bold text-lg">{lvl}</span>
                {isInProgress && <div className="w-1.5 h-1.5 rounded-full bg-blue-500 absolute bottom-2"></div>}
              </button>
            );
          })}
        </div>

        {/* Replay Confirmation Modal */}
        {replayLevelId && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/10 backdrop-blur-sm px-4 animate-fade-in">
                <div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                    <h3 className="text-lg font-bold text-stone-800 mb-2">Replay Level {replayLevelId}?</h3>
                    <p className="text-stone-500 text-sm mb-6">This will reset your progress on this level.</p>
                    <div className="flex gap-3">
                        <button onClick={() => setReplayLevelId(null)} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium active:scale-95 transition">Cancel</button>
                        <button onClick={confirmReplay} className="flex-1 py-3 text-white bg-blue-500 rounded-xl font-medium shadow-md active:scale-95 transition">Replay</button>
                    </div>
                </div>
            </div>
        )}

        {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  // 4. Game Screen
  if (screen === 'game' && selectedDifficulty && selectedLevel) {
    return (
      <div className="h-screen w-full bg-paper">
         <SudokuGame 
            difficulty={selectedDifficulty}
            levelId={selectedLevel}
            onBack={() => setScreen('levels')}
            onComplete={() => {}} 
            onSettingsOpen={() => setShowSettings(true)}
            onNextLevel={handleNextLevel}
            settings={settings}
         />
         {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  return null;
}

export default App;

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { Board, Cell, Difficulty, LevelProgress } from '../types';
import { generateLevel, isValid, isGameSolved } from '../utils/sudoku';
import { Storage } from '../utils/storage';
import { Icons } from './ui/Icons';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  onNextLevel: () => void;
  settings: any;
}

export const SudokuGame: React.FC<SudokuGameProps> = ({ 
  difficulty, 
  levelId, 
  onBack, 
  onComplete, 
  onSettingsOpen,
  onNextLevel,
  settings 
}) => {
  const [board, setBoard] = useState<Board>([]);
  const [solvedBoard, setSolvedBoard] = useState<number[][]>([]);
  const [selectedCell, setSelectedCell] = useState<[number, number] | null>(null);
  const [isPencilMode, setIsPencilMode] = useState(false);
  const [history, setHistory] = useState<Board[]>([]);
  const [timer, setTimer] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [loading, setLoading] = useState(true);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);

  // Transition states for pause menu interactions
  const [isResuming, setIsResuming] = useState(false);
  const [isRestarting, setIsRestarting] = useState(false);
  const [isQuitting, setIsQuitting] = useState(false);

  const timerRef = useRef<any>(null);

  // Initialize Game Logic
  const initializeGame = useCallback(() => {
    setLoading(true);
    setShowRestartConfirm(false);
    setIsPaused(false);
    setIsCompleted(false);
    setIsResuming(false);
    setIsRestarting(false);
    setIsQuitting(false);
    setHistory([]);

    const savedProgress = Storage.getLevelProgress(difficulty, levelId);

    if (savedProgress && savedProgress.status === 'in-progress' && savedProgress.boardState) {
      setBoard(savedProgress.boardState);
      setTimer(savedProgress.timeElapsed);
      const { solved } = generateLevel(difficulty, levelId); 
      setSolvedBoard(solved);
    } else {
      const { initial, solved } = generateLevel(difficulty, levelId);
      setBoard(initial);
      setSolvedBoard(solved);
      setTimer(0);
    }
    setLoading(false);
  }, [difficulty, levelId]);

  useEffect(() => {
    initializeGame();
    return () => stopTimer();
  }, [initializeGame]);

  const handleRestart = () => {
      setIsRestarting(true);
      setTimeout(() => {
        Storage.clearLevelProgress(difficulty, levelId);
        initializeGame();
      }, 300);
  };

  const handleResume = () => {
      setIsResuming(true);
      setTimeout(() => {
          setIsPaused(false);
          setIsResuming(false);
      }, 300);
  };

  const handleQuit = () => {
      setIsQuitting(true);
      setTimeout(() => {
          onBack();
      }, 300);
  };

  const handleNextLevelWithAnim = () => {
      setIsQuitting(true); // Re-use quitting anim style for fading out
      setTimeout(() => {
          onNextLevel();
      }, 300);
  };

  // Timer Logic
  const startTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = setInterval(() => {
      setTimer((t) => t + 1);
    }, 1000);
  };

  const stopTimer = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  useEffect(() => {
    if (!loading && !isPaused && !isCompleted && !showRestartConfirm) {
      startTimer();
    } else {
      stopTimer();
    }
    return () => stopTimer();
  }, [loading, isPaused, isCompleted, showRestartConfirm]);

  // Auto-save
  useEffect(() => {
    if (loading || isCompleted || showRestartConfirm) return;

    const save = setTimeout(() => {
      const progress: LevelProgress = {
        levelId,
        difficulty,
        status: 'in-progress',
        timeElapsed: timer,
        lastPlayed: Date.now(),
        boardState: board,
      };
      Storage.saveLevelProgress(progress);
    }, 1000);

    return () => clearTimeout(save);
  }, [board, timer, difficulty, levelId, loading, isCompleted, showRestartConfirm]);

  // Calculate Conflicts
  const conflicts = useMemo(() => {
      const conf = new Set<string>();
      if (loading || board.length === 0) return conf;

      const rows = Array.from({length: 9}, () => new Map<number, number[]>());
      const cols = Array.from({length: 9}, () => new Map<number, number[]>());
      const boxes = Array.from({length: 9}, () => new Map<number, number[]>());

      board.forEach((row, r) => {
          row.forEach((cell, c) => {
              if (cell.value !== null) {
                  const val = cell.value;
                  if (!rows[r].has(val)) rows[r].set(val, []);
                  rows[r].get(val)!.push(c);

                  if (!cols[c].has(val)) cols[c].set(val, []);
                  cols[c].get(val)!.push(r);

                  const b = Math.floor(r/3)*3 + Math.floor(c/3);
                  if (!boxes[b].has(val)) boxes[b].set(val, []);
                  boxes[b].get(val)!.push(r*9+c);
              }
          });
      });

      // Populate conflicts set
      rows.forEach((rowMap, r) => rowMap.forEach((indices) => {
          if (indices.length > 1) indices.forEach(c => conf.add(`${r}-${c}`));
      }));
      cols.forEach((colMap, c) => colMap.forEach((indices) => {
          if (indices.length > 1) indices.forEach(r => conf.add(`${r}-${c}`));
      }));
      boxes.forEach((boxMap, b) => boxMap.forEach((indices) => {
          if (indices.length > 1) indices.forEach(flat => {
              const r = Math.floor(flat/9);
              const c = flat%9;
              conf.add(`${r}-${c}`);
          });
      }));

      return conf;
  }, [board, loading]);


  const handleCellClick = (row: number, col: number) => {
    if (isPaused || isCompleted) return;
    setSelectedCell([row, col]);
  };

  const handleNumberInput = (num: number) => {
    if (!selectedCell || isPaused || isCompleted) return;
    const [r, c] = selectedCell;
    const currentCell = board[r][c];

    if (currentCell.isFixed) return;

    // Push to history
    setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);

    const newBoard = [...board];
    const newCell = { ...newBoard[r][c] };

    if (isPencilMode) {
      if (newCell.notes.includes(num)) {
        newCell.notes = newCell.notes.filter(n => n !== num);
      } else {
        newCell.notes = [...newCell.notes, num].sort();
      }
    } else {
      // Set value
      if (newCell.value === num) {
        newCell.value = null; 
        newCell.isError = false;
      } else {
        newCell.value = num as any;
        newCell.notes = [];

        // Error Logic (for easy modes that show instant feedback based on solution)
        const isHarderDifficulty = 
            difficulty === Difficulty.Normal || 
            difficulty === Difficulty.Hard || 
            difficulty === Difficulty.Intense || 
            difficulty === Difficulty.Impossible;

        if (!isHarderDifficulty) {
             newCell.isError = num !== solvedBoard[r][c];
        } else {
             newCell.isError = false; // Reset, rely on conflict calc
        }
      }
    }

    newBoard[r][c] = newCell;
    setBoard(newBoard);

    if (!isPencilMode && newCell.value) {
       checkCompletion(newBoard);
    }
  };

  const checkCompletion = (currentBoard: Board) => {
      let filled = 0;
      let correct = 0;
      for(let r=0; r<9; r++) {
          for(let c=0; c<9; c++) {
              if (currentBoard[r][c].value !== null) {
                  filled++;
                  if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
              }
          }
      }

      if (filled === 81 && correct === 81) {
          setIsCompleted(true);
          stopTimer();

          const progress: LevelProgress = {
            levelId,
            difficulty,
            status: 'completed',
            timeElapsed: timer,
            lastPlayed: Date.now(),
            boardState: undefined, 
          };
          Storage.saveLevelProgress(progress);
      }
  };

  const handleErase = () => {
    if (!selectedCell || isPaused) return;
    const [r, c] = selectedCell;
    if (board[r][c].isFixed) return;

    setHistory(prev => [...prev, JSON.parse(JSON.stringify(board))]);
    const newBoard = [...board];
    newBoard[r][c].value = null;
    newBoard[r][c].notes = [];
    newBoard[r][c].isError = false;
    setBoard(newBoard);
  };

  const handleUndo = () => {
    if (history.length === 0 || isPaused) return;
    const previous = history[history.length - 1];
    setBoard(previous);
    setHistory(prev => prev.slice(0, -1));
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const getCellClass = (cell: Cell, r: number, c: number) => {
    let base = "w-full h-full flex items-center justify-center text-lg sm:text-2xl transition-colors duration-200 cursor-pointer select-none relative ";
    const borderR = (c + 1) % 3 === 0 && c !== 8 ? "border-r-2 border-stone-300" : "border-r border-stone-200";
    const borderB = (r + 1) % 3 === 0 && r !== 8 ? "border-b-2 border-stone-300" : "border-b border-stone-200";
    base += `${borderR} ${borderB} `;

    const isConflict = conflicts.has(`${r}-${c}`);

    // Base State
    if (selectedCell) {
        const [sr, sc] = selectedCell;
        const isSelected = sr === r && sc === c;
        const isRelated = sr === r || sc === c || (Math.floor(sr/3) === Math.floor(r/3) && Math.floor(sc/3) === Math.floor(c/3));
        const isSameValue = cell.value !== null && board[sr][sc].value === cell.value;

        if (isSelected) {
            base += "bg-blue-300 text-white "; 
        } else if (settings.highlight && isSameValue) {
            base += "bg-blue-100 "; 
        } else if (settings.highlight && isRelated) {
            base += "bg-stone-100 ";
        } else {
             base += "bg-white ";
        }
    } else {
        base += "bg-white ";
    }

    // Error Overrides
    if (cell.isError || isConflict) {
        if (selectedCell && selectedCell[0] === r && selectedCell[1] === c) {
             // Keep selected style (blue bg), but maybe change text color if possible?
             // Actually user asked for red background. Red bg usually implies bad state.
             // If selected, we prioritize selection color usually, but let's try to mix or override.
             // Let's override background to light red if it's a conflict, UNLESS it's the specific selected cell which we want to track.
             // Standard UX: Selected cell is Blue. Conflicting cells are Red.
             // If selected cell IS the conflict, it stays Blue (selected) but maybe text is Red.
        } else {
             // Replace any background with red background
             base = base.replace(/bg-\w+-\d+/, "") + " bg-red-100 ";
        }
        base += "text-red-500 ";
    } else if (cell.isFixed) {
        base += "font-semibold text-stone-900 ";
    } else {
        base += "font-medium text-blue-600 ";
    }
    return base;
  };

  if (loading) return <div className="h-full w-full flex items-center justify-center">Loading...</div>;

  return (
    <div className={`h-full flex flex-col max-w-lg mx-auto p-4 relative ${isQuitting ? 'animate-fade-out' : 'animate-fade-in'}`}>
      {/* Header */}
      <div className="flex justify-between items-center mb-6 relative">
        <button onClick={handleQuit} className="p-2 rounded-full hover:bg-stone-200 transition z-10">
          <Icons.Back className="w-6 h-6 text-stone-600" />
        </button>

        {/* Centered Title */}
        <div className="absolute left-1/2 -translate-x-1/2 flex flex-col items-center">
            <span className="text-xs font-bold tracking-wider text-stone-400 uppercase text-center w-48">{difficulty} &bull; Level {levelId}</span>
            <span className="text-xl font-medium tabular-nums text-stone-700">{formatTime(timer)}</span>
        </div>

        <div className="flex gap-1 z-10">
            <button onClick={() => setIsPaused(true)} className="p-2 rounded-full hover:bg-stone-200 transition">
                <Icons.Pause className="w-6 h-6 text-stone-600" />
            </button>
            <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200 transition">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>
      </div>

      {/* Board */}
      <div className="aspect-square w-full bg-stone-300 border-2 border-stone-300 rounded-lg overflow-hidden shadow-sm">
        <div className="grid grid-rows-9 h-full">
          {board.map((row, rIndex) => (
            <div key={rIndex} className="grid grid-cols-9 h-full">
              {row.map((cell, cIndex) => (
                <div 
                    key={`${rIndex}-${cIndex}`} 
                    className={getCellClass(cell, rIndex, cIndex)}
                    onClick={() => handleCellClick(rIndex, cIndex)}
                >
                  {cell.value ? (
                      <span>{cell.value}</span>
                  ) : (
                      <div className="grid grid-cols-3 w-full h-full p-0.5">
                          {[1,2,3,4,5,6,7,8,9].map(n => (
                              <div key={n} className="flex items-center justify-center text-[8px] sm:text-[10px] leading-none text-stone-500">
                                  {cell.notes.includes(n) ? n : ''}
                              </div>
                          ))}
                      </div>
                  )}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* Controls */}
      <div className="mt-8 flex flex-col gap-4">
        {/* Actions */}
        <div className="flex justify-between px-4">
            <button onClick={handleUndo} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Undo className="w-5 h-5" /></div>
                <span className="text-xs">Undo</span>
            </button>
            <button onClick={() => setIsPencilMode(!isPencilMode)} className={`flex flex-col items-center gap-1 active:scale-95 transition ${isPencilMode ? 'text-blue-500' : 'text-stone-500'}`}>
                <div className={`p-3 rounded-full shadow-sm border border-stone-100 ${isPencilMode ? 'bg-blue-50 border-blue-200' : 'bg-white'}`}>
                    <Icons.Pencil className="w-5 h-5" />
                    {isPencilMode && <span className="absolute top-0 right-0 w-2 h-2 bg-blue-500 rounded-full"></span>}
                </div>
                <span className="text-xs">Pencil</span>
            </button>
            <button onClick={handleErase} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Erase className="w-5 h-5" /></div>
                <span className="text-xs">Erase</span>
            </button>
             <button className="flex flex-col items-center gap-1 text-stone-300 cursor-not-allowed">
                <div className="p-3 bg-stone-50 rounded-full border border-stone-100"><Icons.Hint className="w-5 h-5" /></div>
                <span className="text-xs">Hint</span>
            </button>
        </div>

        {/* Numpad */}
        <div className="grid grid-cols-9 gap-1 mt-2">
            {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                <button
                    key={num}
                    onClick={() => handleNumberInput(num)}
                    className="aspect-[4/5] flex items-center justify-center text-xl font-medium text-blue-600 bg-white rounded-lg shadow-sm border-b-2 border-stone-100 active:border-b-0 active:translate-y-[2px] transition-all"
                >
                    {num}
                </button>
            ))}
        </div>
      </div>

      {/* Pause Modal */}
      {isPaused && !showRestartConfirm && (
          <div className={`absolute inset-0 bg-stone-50/90 backdrop-blur-sm z-40 flex flex-col items-center justify-center ${isResuming ? 'animate-fade-out' : 'animate-fade-in'}`}>
              <h2 className="text-2xl font-bold text-stone-800 mb-8">Game Paused</h2>
              <div className="flex flex-col gap-4 w-48">
                <button onClick={handleResume} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                    <Icons.Play className="w-5 h-5" /> Resume
                </button>
                <button 
                    onClick={() => setShowRestartConfirm(true)} 
                    className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 rounded-xl active:scale-95 transition hover:bg-stone-50"
                >
                    <Icons.Reset className="w-5 h-5" /> Restart Level
                </button>
                <button onClick={handleQuit} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 transition">
                     Quit Game
                </button>
              </div>
          </div>
      )}

      {/* Restart Confirmation Modal */}
      {showRestartConfirm && (
          <div className={`absolute inset-0 z-50 flex items-center justify-center bg-black/10 backdrop-blur-sm px-4 ${isRestarting ? 'animate-fade-out' : 'animate-fade-in'}`}>
             <div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                <h3 className="text-lg font-bold text-stone-800 mb-2">Restart Level?</h3>
                <p className="text-stone-500 text-sm mb-6">Are you sure? This will reset all progress on this level.</p>
                <div className="flex gap-3">
                   <button onClick={() => setShowRestartConfirm(false)} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium active:scale-95 transition">Cancel</button>
                   <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                </div>
             </div>
          </div>
      )}

      {/* Completion Modal */}
      {isCompleted && (
          <div className="absolute inset-0 bg-green-500/50 backdrop-blur-sm z-50 flex flex-col items-center justify-center text-white animate-fade-in">
              <div className="bg-white text-stone-800 p-8 rounded-2xl shadow-2xl w-80 text-center animate-pop">
                  <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6 text-green-500">
                      <Icons.Check className="w-10 h-10 animate-scale-loop" />
                  </div>
                  <h2 className="text-2xl font-bold mb-2">Solved!</h2>
                  <p className="text-stone-500 mb-2 text-sm">Finished in</p>
                  <p className="text-3xl font-medium mb-8 tabular-nums">{formatTime(timer)}</p>

                  <div className="flex flex-col gap-3">
                    <button onClick={handleNextLevelWithAnim} className="w-full py-3 bg-stone-800 text-white rounded-xl font-medium hover:bg-stone-700 active:scale-95 transition shadow-lg active:opacity-80">
                        Play Next Level
                    </button>
                    <button onClick={handleQuit} className="w-full py-3 bg-white text-stone-600 border border-stone-200 rounded-xl font-medium hover:bg-stone-50 active:scale-95 transition active:opacity-80">
                        Back to Menu
                    </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { Icons } from './components/ui/Icons';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings';

interface SettingsModalProps {
    settings: AppSettings;
    onToggle: (key: keyof AppSettings) => void;
    onReset: () => void;
    onClose: () => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ settings, onToggle, onReset, onClose }) => {
    const [isClosing, setIsClosing] = useState(false);

    const handleClose = () => {
        setIsClosing(true);
        setTimeout(() => {
            onClose();
        }, 300); // Match animation duration
    };

    return (
        <div className={`fixed inset-0 z-[100] bg-black/20 backdrop-blur-sm flex items-end sm:items-center justify-center ${isClosing ? 'animate-fade-out' : 'animate-fade-in'}`} onClick={handleClose}>
            <div 
                className={`bg-white w-full max-w-md p-6 rounded-t-3xl sm:rounded-3xl shadow-2xl ${isClosing ? 'animate-slide-down' : 'animate-slide-up'}`} 
                onClick={e => e.stopPropagation()}
            >
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold text-stone-800">Settings</h3>
                    <button onClick={handleClose} className="p-2 bg-stone-100 rounded-full hover:bg-stone-200"><Icons.Close className="w-5 h-5" /></button>
                </div>

                <div className="space-y-4">
                    <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                        <div className="flex items-center gap-3 text-stone-700">
                            <Icons.Sound className="w-5 h-5" />
                            <span>Sound Effects</span>
                        </div>
                        <button onClick={() => onToggle('sound')} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings.sound ? 'bg-green-500' : 'bg-stone-300'}`}>
                            <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings.sound ? 'translate-x-5' : 'translate-x-0'}`}></div>
                        </button>
                    </div>
                    <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                        <div className="flex items-center gap-3 text-stone-700">
                            <Icons.Eye className="w-5 h-5" />
                            <span>Highlight Areas</span>
                        </div>
                        <button onClick={() => onToggle('highlight')} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings.highlight ? 'bg-green-500' : 'bg-stone-300'}`}>
                            <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings.highlight ? 'translate-x-5' : 'translate-x-0'}`}></div>
                        </button>
                    </div>
                    {/* More settings can go here */}
                </div>

                <div className="mt-8 pt-6 border-t border-stone-100">
                    <button onClick={onReset} className="w-full py-3 flex items-center justify-center gap-2 text-red-500 hover:bg-red-50 rounded-xl transition">
                        <Icons.Trash className="w-5 h-5" /> Reset All Progress
                    </button>
                </div>
            </div>
        </div>
    );
};

function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);

  // Transition State
  const [isTransitioning, setIsTransitioning] = useState(false);

  // Splash Screen Effect
  useEffect(() => {
    const timer = setTimeout(() => {
      setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  const handleDifficultySelect = (diff: Difficulty) => {
    setIsTransitioning(true);
    setTimeout(() => {
        setSelectedDifficulty(diff);
        setScreen('levels');
        setIsTransitioning(false);
    }, 300);
  };

  const handleLevelBack = () => {
    setIsTransitioning(true);
    setTimeout(() => {
        setScreen('difficulty');
        setIsTransitioning(false);
    }, 300);
  };

  const handleLevelSelect = (levelId: number) => {
    // Check if level is completed
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        setReplayLevelId(levelId);
    } else {
        setIsTransitioning(true);
        setTimeout(() => {
            setSelectedLevel(levelId);
            setScreen('game');
            setIsTransitioning(false);
        }, 300);
    }
  };

  const confirmReplay = () => {
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setIsTransitioning(true);
          setReplayLevelId(null);
          setTimeout(() => {
             setSelectedLevel(replayLevelId);
             setScreen('game');
             setIsTransitioning(false);
          }, 300);
      }
  };

  const handleNextLevel = () => {
      if (selectedLevel && selectedLevel < 30) {
          setSelectedLevel(selectedLevel + 1);
      } else {
          setScreen('levels');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  // --- Render Components ---

  // 1. Splash
  if (screen === 'splash') {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-stone-50">
        <div className="animate-fade-in flex flex-col items-center">
            <div className="w-20 h-20 bg-stone-800 rounded-2xl mb-6 shadow-xl flex items-center justify-center">
                <div className="grid grid-cols-2 gap-1">
                    <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                    <div className="w-3 h-3 bg-white rounded-sm"></div>
                    <div className="w-3 h-3 bg-white rounded-sm"></div>
                    <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                </div>
            </div>
          <h1 className="text-3xl font-light tracking-widest text-stone-800">MINIMAL</h1>
          <h2 className="text-xl font-bold tracking-widest text-stone-400">SUDOKU</h2>
        </div>
      </div>
    );
  }

  // 2. Difficulty Selection
  if (screen === 'difficulty') {
    const difficulties = Object.values(Difficulty);
    return (
      <div className={`min-h-screen bg-paper text-stone-800 p-6 flex flex-col items-center ${isTransitioning ? 'animate-fade-out' : 'animate-fade-in'}`}>
        <div className="w-full max-w-md flex justify-between items-center mb-8 mt-4">
            <div>
                <h1 className="text-2xl font-bold">New Game</h1>
                <p className="text-stone-400 text-sm">Select your challenge</p>
            </div>
            <button onClick={() => setShowSettings(true)} className="p-2 bg-white rounded-full shadow-sm hover:shadow-md transition">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>

        <div className="w-full max-w-md grid grid-cols-2 gap-4">
          {difficulties.map((diff) => {
             const completed = Storage.getCompletedCount(diff);
             return (
                <button
                key={diff}
                onClick={() => handleDifficultySelect(diff)}
                className="bg-white p-6 rounded-2xl shadow-sm border border-stone-100 flex flex-col items-start gap-2 hover:border-blue-200 hover:shadow-md transition-all active:scale-95 text-left"
                >
                <span className="text-lg font-semibold text-stone-700">{diff}</span>
                <span className="text-xs text-stone-400 font-medium tracking-wide">{completed} / 30 Solved</span>
                <div className="w-full h-1 bg-stone-100 rounded-full mt-2 overflow-hidden">
                    <div className="h-full bg-stone-800" style={{ width: `${(completed/30)*100}%` }}></div>
                </div>
                </button>
            )
          })}
        </div>
        {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  // 3. Level Selection
  if (screen === 'levels' && selectedDifficulty) {
    const levels = Array.from({ length: 30 }, (_, i) => i + 1);

    return (
      <div className={`min-h-screen bg-paper p-6 flex flex-col items-center ${isTransitioning ? 'animate-fade-out' : 'animate-fade-in'}`}>
        <div className="w-full max-w-md flex items-center mb-8 mt-4 relative">
            <button onClick={handleLevelBack} className="absolute left-0 p-2 rounded-full hover:bg-stone-200 transition">
                <Icons.Back className="w-6 h-6" />
            </button>
            <div className="w-full text-center">
                <h1 className="text-xl font-bold">{selectedDifficulty}</h1>
                <p className="text-xs text-stone-400 uppercase tracking-widest">Select Level</p>
            </div>
             <button onClick={() => setShowSettings(true)} className="absolute right-0 p-2 rounded-full hover:bg-stone-200">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>

        <div className="w-full max-w-md grid grid-cols-5 gap-3">
          {levels.map((lvl) => {
            const progress = Storage.getLevelProgress(selectedDifficulty, lvl);
            const isCompleted = progress?.status === 'completed';
            const isInProgress = progress?.status === 'in-progress';

            return (
              <button
                key={lvl}
                onClick={() => handleLevelSelect(lvl)}
                className={`
                  aspect-square rounded-xl flex flex-col items-center justify-center relative transition-all active:scale-90
                  ${isCompleted 
                    ? 'bg-stone-100 text-stone-300 border border-stone-100' // Greyed out for completed
                    : isInProgress 
                        ? 'bg-white border-2 border-blue-400 shadow-md text-stone-800' 
                        : 'bg-white border border-stone-100 shadow-sm hover:shadow-md text-stone-800'}
                `}
              >
                <span className="font-bold text-lg">{lvl}</span>
                {isInProgress && <div className="w-1.5 h-1.5 rounded-full bg-blue-500 absolute bottom-2"></div>}
              </button>
            );
          })}
        </div>

        {/* Replay Confirmation Modal */}
        {replayLevelId && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/10 backdrop-blur-sm px-4 animate-fade-in">
                <div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                    <h3 className="text-lg font-bold text-stone-800 mb-2">Replay Level {replayLevelId}?</h3>
                    <p className="text-stone-500 text-sm mb-6">This will reset your progress on this level.</p>
                    <div className="flex gap-3">
                        <button onClick={() => setReplayLevelId(null)} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium active:scale-95 transition">Cancel</button>
                        <button onClick={confirmReplay} className="flex-1 py-3 text-white bg-blue-500 rounded-xl font-medium shadow-md active:scale-95 transition">Replay</button>
                    </div>
                </div>
            </div>
        )}

        {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  // 4. Game Screen
  if (screen === 'game' && selectedDifficulty && selectedLevel) {
    return (
      <div className="h-screen w-full bg-paper">
         <SudokuGame 
            difficulty={selectedDifficulty}
            levelId={selectedLevel}
            onBack={() => setScreen('levels')}
            onComplete={() => {}} 
            onSettingsOpen={() => setShowSettings(true)}
            onNextLevel={handleNextLevel}
            settings={settings}
         />
         {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  return null;
}

export default App;

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { Board, Cell, Difficulty, LevelProgress } from '../types';
import { generateLevel, isValid, isGameSolved } from '../utils/sudoku';
import { Storage } from '../utils/storage';
import { Icons } from './ui/Icons';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  onNextLevel: () => void;
  settings: any;
}

export const SudokuGame: React.FC<SudokuGameProps> = ({ 
  difficulty, 
  levelId, 
  onBack, 
  onComplete, 
  onSettingsOpen,
  onNextLevel,
  settings 
}) => {
  const [board, setBoard] = useState<Board>([]);
  const [solvedBoard, setSolvedBoard] = useState<number[][]>([]);
  const [selectedCell, setSelectedCell] = useState<[number, number] | null>(null);
  const [isPencilMode, setIsPencilMode] = useState(false);
  const [history, setHistory] = useState<Board[]>([]);
  const [timer, setTimer] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [loading, setLoading] = useState(true);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);

  // Transition states for pause menu interactions
  const [isResuming, setIsResuming] = useState(false);
  const [isRestarting, setIsRestarting] = useState(false);
  const [isQuitting, setIsQuitting] = useState(false);

  const timerRef = useRef<any>(null);

  // Initialize Game Logic
  const initializeGame = useCallback(() => {
    setLoading(true);
    setShowRestartConfirm(false);
    setIsPaused(false);
    setIsCompleted(false);
    setIsResuming(false);
    setIsRestarting(false);
    setIsQuitting(false);
    setHistory([]);

    const savedProgress = Storage.getLevelProgress(difficulty, levelId);

    if (savedProgress && savedProgress.status === 'in-progress' && savedProgress.boardState) {
      setBoard(savedProgress.boardState);
      setTimer(savedProgress.timeElapsed);
      const { solved } = generateLevel(difficulty, levelId); 
      setSolvedBoard(solved);
    } else {
      const { initial, solved } = generateLevel(difficulty, levelId);
      setBoard(initial);
      setSolvedBoard(solved);
      setTimer(0);
    }
    setLoading(false);
  }, [difficulty, levelId]);

  useEffect(() => {
    initializeGame();
    return () => stopTimer();
  }, [initializeGame]);

  const handleRestart = () => {
      setIsRestarting(true);
      setTimeout(() => {
        Storage.clearLevelProgress(difficulty, levelId);
        initializeGame();
      }, 300);
  };

  const handleResume = () => {
      setIsResuming(true);
      setTimeout(() => {
          setIsPaused(false);
          setIsResuming(false);
      }, 300);
  };

  const handleQuit = () => {
      setIsQuitting(true);
      setTimeout(() => {
          onBack();
      }, 300);
  };

  const handleNextLevelWithAnim = () => {
      setIsQuitting(true); // Re-use quitting anim style for fading out
      setTimeout(() => {
          onNextLevel();
      }, 300);
  };

  // Timer Logic
  const startTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = setInterval(() => {
      setTimer((t) => t + 1);
    }, 1000);
  };

  const stopTimer = () => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  useEffect(() => {
    if (!loading && !isPaused && !isCompleted && !showRestartConfirm) {
      startTimer();
    } else {
      stopTimer();
    }
    return () => stopTimer();
  }, [loading, isPaused, isCompleted, showRestartConfirm]);

  // Auto-save
  useEffect(() => {
    if (loading || isCompleted || showRestartConfirm) return;

    const save = setTimeout(() => {
      const progress: LevelProgress = {
        levelId,
        difficulty,
        status: 'in-progress',
        timeElapsed: timer,
        lastPlayed: Date.now(),
        boardState: board,
      };
      Storage.saveLevelProgress(progress);
    }, 1000);

    return () => clearTimeout(save);
  }, [board, timer, difficulty, levelId, loading, isCompleted, showRestartConfirm]);

  // Calculate Conflicts
  const conflicts = useMemo(() => {
      const conf = new Set<string>();
      if (loading || board.length === 0) return conf;

      const rows = Array.from({length: 9}, () => new Map<number, number[]>());
      const cols = Array.from({length: 9}, () => new Map<number, number[]>());
      const boxes = Array.from({length: 9}, () => new Map<number, number[]>());

      board.forEach((row, r) => {
          row.forEach((cell, c) => {
              if (cell.value !== null) {
                  const val = cell.value;
                  if (!rows[r].has(val)) rows[r].set(val, []);
                  rows[r].get(val)!.push(c);

                  if (!cols[c].has(val)) cols[c].set(val, []);
                  cols[c].get(val)!.push(r);

                  const b = Math.floor(r/3)*3 + Math.floor(c/3);
                  if (!boxes[b].has(val)) boxes[b].set(val, []);
                  boxes[b].get(val)!.push(r*9+c);
              }
          });
      });

      // Populate conflicts set
      rows.forEach((rowMap, r) => rowMap.forEach((indices) => {
          if (indices.length > 1) indices.forEach(c => conf.add(`${r}-${c}`));
      }));
      cols.forEach((colMap, c) => colMap.forEach((indices) => {
          if (indices.length > 1) indices.forEach(r => conf.add(`${r}-${c}`));
      }));
      boxes.forEach((boxMap, b) => boxMap.forEach((indices) => {
          if (indices.length > 1) indices.forEach(flat => {
              const r = Math.floor(flat/9);
              const c = flat%9;
              conf.add(`${r}-${c}`);
          });
      }));

      return conf;
  }, [board, loading]);

  const handleCellClick = (row: number, col: number) => {
    if (isPaused || isCompleted) return;
    setSelectedCell([row, col]);
  };

  const handleNumberInput = (num: number) => {
    if (!selectedCell || isPaused || isCompleted) return;
    const [r, c] = selectedCell;
    const currentCell = board[r][c];

    if (currentCell.isFixed) return;

    // Push to history
    setHistory(prev => [...prev.slice(-20), JSON.parse(JSON.stringify(board))]);

    const newBoard = [...board];
    const newCell = { ...newBoard[r][c] };

    if (isPencilMode) {
      if (newCell.notes.includes(num)) {
        newCell.notes = newCell.notes.filter(n => n !== num);
      } else {
        newCell.notes = [...newCell.notes, num].sort();
      }
    } else {
      // Set value
      if (newCell.value === num) {
        newCell.value = null; 
        newCell.isError = false;
      } else {
        newCell.value = num as any;
        newCell.notes = [];

        // Error Logic
        const isHarderDifficulty = 
            difficulty === Difficulty.Normal || 
            difficulty === Difficulty.Hard || 
            difficulty === Difficulty.Intense || 
            difficulty === Difficulty.Impossible;

        // Even in harder difficulties, we now rely on 'conflicts' memo for highlighting.
        // We set isError mostly for internal state or end-game check, but visual is handled by conflicts + isError
        if (!isHarderDifficulty) {
             newCell.isError = num !== solvedBoard[r][c];
        } else {
             newCell.isError = false; // We don't mark it as 'isError' data-wise to avoid giving away info, but conflict logic will visually flag it
        }
      }
    }

    newBoard[r][c] = newCell;
    setBoard(newBoard);

    if (!isPencilMode && newCell.value) {
       checkCompletion(newBoard);
    }
  };

  const checkCompletion = (currentBoard: Board) => {
      let filled = 0;
      let correct = 0;
      for(let r=0; r<9; r++) {
          for(let c=0; c<9; c++) {
              if (currentBoard[r][c].value !== null) {
                  filled++;
                  if (currentBoard[r][c].value === solvedBoard[r][c]) correct++;
              }
          }
      }

      if (filled === 81 && correct === 81) {
          setIsCompleted(true);
          stopTimer();

          const progress: LevelProgress = {
            levelId,
            difficulty,
            status: 'completed',
            timeElapsed: timer,
            lastPlayed: Date.now(),
            boardState: undefined, 
          };
          Storage.saveLevelProgress(progress);
      }
  };

  const handleErase = () => {
    if (!selectedCell || isPaused) return;
    const [r, c] = selectedCell;
    if (board[r][c].isFixed) return;

    setHistory(prev => [...prev, JSON.parse(JSON.stringify(board))]);
    const newBoard = [...board];
    newBoard[r][c].value = null;
    newBoard[r][c].notes = [];
    newBoard[r][c].isError = false;
    setBoard(newBoard);
  };

  const handleUndo = () => {
    if (history.length === 0 || isPaused) return;
    const previous = history[history.length - 1];
    setBoard(previous);
    setHistory(prev => prev.slice(0, -1));
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const getCellClass = (cell: Cell, r: number, c: number) => {
    let classes = "w-full h-full flex items-center justify-center text-lg sm:text-2xl transition-all duration-200 cursor-pointer select-none relative ";
    const borderR = (c + 1) % 3 === 0 && c !== 8 ? "border-r-2 border-stone-300" : "border-r border-stone-200";
    const borderB = (r + 1) % 3 === 0 && r !== 8 ? "border-b-2 border-stone-300" : "border-b border-stone-200";
    classes += `${borderR} ${borderB} `;

    const isConflict = conflicts.has(`${r}-${c}`);
    const isError = cell.isError;
    const isSelected = selectedCell ? (selectedCell[0] === r && selectedCell[1] === c) : false;
    const isSameValue = selectedCell && cell.value !== null && board[selectedCell[0]][selectedCell[1]].value === cell.value;
    const isRelated = selectedCell && (selectedCell[0] === r || selectedCell[1] === c || (Math.floor(selectedCell[0]/3) === Math.floor(r/3) && Math.floor(selectedCell[1]/3) === Math.floor(c/3)));

    // Background Priority
    if (isError || isConflict) {
        classes += "bg-red-100 ";
        // If selected and error, we need to show selection state somehow. Ring works best.
        if (isSelected) classes += "ring-2 ring-blue-400 z-10 ";
    } else if (isSelected) {
        classes += "bg-blue-300 ";
    } else if (settings.highlight && isSameValue) {
        classes += "bg-blue-100 ";
    } else if (settings.highlight && isRelated) {
        classes += "bg-stone-100 ";
    } else {
        classes += "bg-white ";
    }

    // Text Color Priority
    if (cell.isFixed) {
        classes += "font-semibold text-stone-900 ";
    } else {
        // User Input (even if error, user requested blue text)
        if (isSelected && !isError && !isConflict) {
             classes += "font-medium text-white "; // White text on blue selection
        } else {
             classes += "font-medium text-blue-600 ";
        }
    }
    return classes;
  };

  if (loading) return <div className="h-full w-full flex items-center justify-center">Loading...</div>;

  return (
    <div className={`h-full flex flex-col max-w-lg mx-auto p-4 relative ${isQuitting ? 'animate-fade-out' : 'animate-fade-in'}`}>
      {/* Header */}
      <div className="flex justify-between items-center mb-6 relative">
        <button onClick={handleQuit} className="p-2 rounded-full hover:bg-stone-200 transition z-10">
          <Icons.Back className="w-6 h-6 text-stone-600" />
        </button>

        {/* Centered Title */}
        <div className="absolute left-1/2 -translate-x-1/2 flex flex-col items-center">
            <span className="text-xs font-bold tracking-wider text-stone-400 uppercase text-center w-48">{difficulty} &bull; Level {levelId}</span>
            <span className="text-xl font-medium tabular-nums text-stone-700">{formatTime(timer)}</span>
        </div>

        <div className="flex gap-1 z-10">
            <button onClick={() => setIsPaused(true)} className="p-2 rounded-full hover:bg-stone-200 transition">
                <Icons.Pause className="w-6 h-6 text-stone-600" />
            </button>
            <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200 transition">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>
      </div>

      {/* Board */}
      <div className="aspect-square w-full bg-stone-300 border-2 border-stone-300 rounded-lg overflow-hidden shadow-sm">
        <div className="grid grid-rows-9 h-full">
          {board.map((row, rIndex) => (
            <div key={rIndex} className="grid grid-cols-9 h-full">
              {row.map((cell, cIndex) => (
                <div 
                    key={`${rIndex}-${cIndex}`} 
                    className={getCellClass(cell, rIndex, cIndex)}
                    onClick={() => handleCellClick(rIndex, cIndex)}
                >
                  {cell.value ? (
                      <span>{cell.value}</span>
                  ) : (
                      <div className="grid grid-cols-3 w-full h-full p-0.5">
                          {[1,2,3,4,5,6,7,8,9].map(n => (
                              <div key={n} className="flex items-center justify-center text-[8px] sm:text-[10px] leading-none text-stone-500">
                                  {cell.notes.includes(n) ? n : ''}
                              </div>
                          ))}
                      </div>
                  )}
                </div>
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* Controls */}
      <div className="mt-8 flex flex-col gap-4">
        {/* Actions */}
        <div className="flex justify-between px-4">
            <button onClick={handleUndo} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Undo className="w-5 h-5" /></div>
                <span className="text-xs">Undo</span>
            </button>
            <button onClick={() => setIsPencilMode(!isPencilMode)} className={`flex flex-col items-center gap-1 active:scale-95 transition ${isPencilMode ? 'text-blue-500' : 'text-stone-500'}`}>
                <div className={`p-3 rounded-full shadow-sm border border-stone-100 ${isPencilMode ? 'bg-blue-50 border-blue-200' : 'bg-white'}`}>
                    <Icons.Pencil className="w-5 h-5" />
                    {isPencilMode && <span className="absolute top-0 right-0 w-2 h-2 bg-blue-500 rounded-full"></span>}
                </div>
                <span className="text-xs">Pencil</span>
            </button>
            <button onClick={handleErase} className="flex flex-col items-center gap-1 text-stone-500 active:scale-95 transition">
                <div className="p-3 bg-white rounded-full shadow-sm border border-stone-100"><Icons.Erase className="w-5 h-5" /></div>
                <span className="text-xs">Erase</span>
            </button>
             <button className="flex flex-col items-center gap-1 text-stone-300 cursor-not-allowed">
                <div className="p-3 bg-stone-50 rounded-full border border-stone-100"><Icons.Hint className="w-5 h-5" /></div>
                <span className="text-xs">Hint</span>
            </button>
        </div>

        {/* Numpad */}
        <div className="grid grid-cols-9 gap-1 mt-2">
            {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                <button
                    key={num}
                    onClick={() => handleNumberInput(num)}
                    className="aspect-[4/5] flex items-center justify-center text-xl font-medium text-blue-600 bg-white rounded-lg shadow-sm border-b-2 border-stone-100 active:border-b-0 active:translate-y-[2px] transition-all"
                >
                    {num}
                </button>
            ))}
        </div>
      </div>

      {/* Pause Modal */}
      {isPaused && !showRestartConfirm && (
          <div className={`absolute inset-0 bg-stone-50/90 backdrop-blur-sm z-40 flex flex-col items-center justify-center ${isResuming ? 'animate-fade-out' : 'animate-fade-in'}`}>
              <h2 className="text-2xl font-bold text-stone-800 mb-8">Game Paused</h2>
              <div className="flex flex-col gap-4 w-48">
                <button onClick={handleResume} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                    <Icons.Play className="w-5 h-5" /> Resume
                </button>
                <button 
                    onClick={() => setShowRestartConfirm(true)} 
                    className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 rounded-xl active:scale-95 transition hover:bg-stone-50"
                >
                    <Icons.Reset className="w-5 h-5" /> Restart Level
                </button>
                <button onClick={handleQuit} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 transition">
                     Quit Game
                </button>
              </div>
          </div>
      )}

      {/* Restart Confirmation Modal */}
      {showRestartConfirm && (
          <div className={`absolute inset-0 z-50 flex items-center justify-center bg-stone-50/90 backdrop-blur-sm px-4 ${isRestarting ? 'animate-fade-out' : 'animate-fade-in'}`}>
             <div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                <h3 className="text-lg font-bold text-stone-800 mb-2">Restart Level?</h3>
                <p className="text-stone-500 text-sm mb-6">Are you sure? This will reset all progress on this level.</p>
                <div className="flex gap-3">
                   <button onClick={() => setShowRestartConfirm(false)} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium active:scale-95 transition">Cancel</button>
                   <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                </div>
             </div>
          </div>
      )}

      {/* Completion Modal */}
      {isCompleted && (
          <div className="absolute inset-0 bg-green-500/50 backdrop-blur-sm z-50 flex flex-col items-center justify-center text-white animate-fade-in">
              <div className="bg-white text-stone-800 p-8 rounded-2xl shadow-2xl w-80 text-center animate-pop">
                  <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6 text-green-500">
                      <Icons.Check className="w-10 h-10 animate-scale-loop" />
                  </div>
                  <h2 className="text-2xl font-bold mb-2">Solved!</h2>
                  <p className="text-stone-500 mb-2 text-sm">Finished in</p>
                  <p className="text-3xl font-medium mb-8 tabular-nums">{formatTime(timer)}</p>

                  <div className="flex flex-col gap-3">
                    <button onClick={handleNextLevelWithAnim} className="w-full py-3 bg-stone-800 text-white rounded-xl font-medium hover:bg-stone-700 active:scale-95 transition shadow-lg active:opacity-80">
                        Play Next Level
                    </button>
                    <button onClick={handleQuit} className="w-full py-3 bg-white text-stone-600 border border-stone-200 rounded-xl font-medium hover:bg-stone-50 active:scale-95 transition active:opacity-80">
                        Back to Menu
                    </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { Icons } from './components/ui/Icons';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings';

interface SettingsModalProps {
    settings: AppSettings;
    onToggle: (key: keyof AppSettings) => void;
    onReset: () => void;
    onClose: () => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ settings, onToggle, onReset, onClose }) => {
    const [isClosing, setIsClosing] = useState(false);

    const handleClose = () => {
        setIsClosing(true);
        setTimeout(() => {
            onClose();
        }, 300); // Match animation duration
    };

    return (
        <div className={`fixed inset-0 z-[100] bg-black/20 backdrop-blur-sm flex items-end sm:items-center justify-center ${isClosing ? 'animate-fade-out' : 'animate-fade-in'}`} onClick={handleClose}>
            <div 
                className={`bg-white w-full max-w-md p-6 rounded-t-3xl sm:rounded-3xl shadow-2xl ${isClosing ? 'animate-slide-down' : 'animate-slide-up'}`} 
                onClick={e => e.stopPropagation()}
            >
                <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold text-stone-800">Settings</h3>
                    <button onClick={handleClose} className="p-2 bg-stone-100 rounded-full hover:bg-stone-200"><Icons.Close className="w-5 h-5" /></button>
                </div>

                <div className="space-y-4">
                    <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                        <div className="flex items-center gap-3 text-stone-700">
                            <Icons.Sound className="w-5 h-5" />
                            <span>Sound Effects</span>
                        </div>
                        <button onClick={() => onToggle('sound')} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings.sound ? 'bg-green-500' : 'bg-stone-300'}`}>
                            <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings.sound ? 'translate-x-5' : 'translate-x-0'}`}></div>
                        </button>
                    </div>
                    <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                        <div className="flex items-center gap-3 text-stone-700">
                            <Icons.Eye className="w-5 h-5" />
                            <span>Highlight Areas</span>
                        </div>
                        <button onClick={() => onToggle('highlight')} className={`w-12 h-7 rounded-full p-1 transition-colors ${settings.highlight ? 'bg-green-500' : 'bg-stone-300'}`}>
                            <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${settings.highlight ? 'translate-x-5' : 'translate-x-0'}`}></div>
                        </button>
                    </div>
                    {/* More settings can go here */}
                </div>

                <div className="mt-8 pt-6 border-t border-stone-100">
                    <button onClick={onReset} className="w-full py-3 flex items-center justify-center gap-2 text-red-500 hover:bg-red-50 rounded-xl transition">
                        <Icons.Trash className="w-5 h-5" /> Reset All Progress
                    </button>
                </div>
            </div>
        </div>
    );
};

function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);

  // Transition State
  const [isTransitioning, setIsTransitioning] = useState(false);

  // Splash Screen Effect
  useEffect(() => {
    const timer = setTimeout(() => {
      setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  const handleDifficultySelect = (diff: Difficulty) => {
    setIsTransitioning(true);
    setTimeout(() => {
        setSelectedDifficulty(diff);
        setScreen('levels');
        setIsTransitioning(false);
    }, 300);
  };

  const handleLevelBack = () => {
    setIsTransitioning(true);
    setTimeout(() => {
        setScreen('difficulty');
        setIsTransitioning(false);
    }, 300);
  };

  const handleGameBack = () => {
    setIsTransitioning(true);
    setTimeout(() => {
        setScreen('levels');
        setIsTransitioning(false);
    }, 300);
  };

  const handleLevelSelect = (levelId: number) => {
    // Check if level is completed
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        setReplayLevelId(levelId);
    } else {
        setIsTransitioning(true);
        setTimeout(() => {
            setSelectedLevel(levelId);
            setScreen('game');
            setIsTransitioning(false);
        }, 300);
    }
  };

  const confirmReplay = () => {
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setIsTransitioning(true);
          setReplayLevelId(null);
          setTimeout(() => {
             setSelectedLevel(replayLevelId);
             setScreen('game');
             setIsTransitioning(false);
          }, 300);
      }
  };

  const handleNextLevel = () => {
      if (selectedLevel && selectedLevel < 30) {
          setSelectedLevel(selectedLevel + 1);
      } else {
          setScreen('levels');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  // --- Render Components ---

  // 1. Splash
  if (screen === 'splash') {
    return (
      <div className="h-screen w-full flex flex-col items-center justify-center bg-stone-50">
        <div className="animate-fade-in flex flex-col items-center">
            <div className="w-20 h-20 bg-stone-800 rounded-2xl mb-6 shadow-xl flex items-center justify-center">
                <div className="grid grid-cols-2 gap-1">
                    <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                    <div className="w-3 h-3 bg-white rounded-sm"></div>
                    <div className="w-3 h-3 bg-white rounded-sm"></div>
                    <div className="w-3 h-3 bg-white rounded-sm opacity-50"></div>
                </div>
            </div>
          <h1 className="text-3xl font-light tracking-widest text-stone-800">MINIMAL</h1>
          <h2 className="text-xl font-bold tracking-widest text-stone-400">SUDOKU</h2>
        </div>
      </div>
    );
  }

  // 2. Difficulty Selection
  if (screen === 'difficulty') {
    const difficulties = Object.values(Difficulty);
    return (
      <div className={`min-h-screen bg-paper text-stone-800 p-6 flex flex-col items-center ${isTransitioning ? 'animate-fade-out' : 'animate-fade-in'}`}>
        <div className="w-full max-w-md flex justify-between items-center mb-8 mt-4">
            <div>
                <h1 className="text-2xl font-bold">New Game</h1>
                <p className="text-stone-400 text-sm">Select your challenge</p>
            </div>
            <button onClick={() => setShowSettings(true)} className="p-2 bg-white rounded-full shadow-sm hover:shadow-md transition">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>

        <div className="w-full max-w-md grid grid-cols-2 gap-4">
          {difficulties.map((diff) => {
             const completed = Storage.getCompletedCount(diff);
             return (
                <button
                key={diff}
                onClick={() => handleDifficultySelect(diff)}
                className="bg-white p-6 rounded-2xl shadow-sm border border-stone-100 flex flex-col items-start gap-2 hover:border-blue-200 hover:shadow-md transition-all active:scale-95 text-left"
                >
                <span className="text-lg font-semibold text-stone-700">{diff}</span>
                <span className="text-xs text-stone-400 font-medium tracking-wide">{completed} / 30 Solved</span>
                <div className="w-full h-1 bg-stone-100 rounded-full mt-2 overflow-hidden">
                    <div className="h-full bg-stone-800" style={{ width: `${(completed/30)*100}%` }}></div>
                </div>
                </button>
            )
          })}
        </div>
        {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  // 3. Level Selection
  if (screen === 'levels' && selectedDifficulty) {
    const levels = Array.from({ length: 30 }, (_, i) => i + 1);

    return (
      <div className={`min-h-screen bg-paper p-6 flex flex-col items-center ${isTransitioning ? 'animate-fade-out' : 'animate-fade-in'}`}>
        <div className="w-full max-w-md flex items-center mb-8 mt-4 relative">
            <button onClick={handleLevelBack} className="absolute left-0 p-2 rounded-full hover:bg-stone-200 transition">
                <Icons.Back className="w-6 h-6" />
            </button>
            <div className="w-full text-center">
                <h1 className="text-xl font-bold">{selectedDifficulty}</h1>
                <p className="text-xs text-stone-400 uppercase tracking-widest">Select Level</p>
            </div>
             <button onClick={() => setShowSettings(true)} className="absolute right-0 p-2 rounded-full hover:bg-stone-200">
                <Icons.Settings className="w-6 h-6 text-stone-600" />
            </button>
        </div>

        <div className="w-full max-w-md grid grid-cols-5 gap-3">
          {levels.map((lvl) => {
            const progress = Storage.getLevelProgress(selectedDifficulty, lvl);
            const isCompleted = progress?.status === 'completed';
            const isInProgress = progress?.status === 'in-progress';

            return (
              <button
                key={lvl}
                onClick={() => handleLevelSelect(lvl)}
                className={`
                  aspect-square rounded-xl flex flex-col items-center justify-center relative transition-all active:scale-90
                  ${isCompleted 
                    ? 'bg-stone-100 text-stone-300 border border-stone-100' // Greyed out for completed
                    : isInProgress 
                        ? 'bg-white border-2 border-blue-400 shadow-md text-stone-800' 
                        : 'bg-white border border-stone-100 shadow-sm hover:shadow-md text-stone-800'}
                `}
              >
                <span className="font-bold text-lg">{lvl}</span>
                {isInProgress && <div className="w-1.5 h-1.5 rounded-full bg-blue-500 absolute bottom-2"></div>}
              </button>
            );
          })}
        </div>

        {/* Replay Confirmation Modal */}
        {replayLevelId && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/10 backdrop-blur-sm px-4 animate-fade-in">
                <div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                    <h3 className="text-lg font-bold text-stone-800 mb-2">Replay Level {replayLevelId}?</h3>
                    <p className="text-stone-500 text-sm mb-6">This will reset your progress on this level.</p>
                    <div className="flex gap-3">
                        <button onClick={() => setReplayLevelId(null)} className="flex-1 py-3 text-stone-600 bg-stone-100 rounded-xl font-medium active:scale-95 transition">Cancel</button>
                        <button onClick={confirmReplay} className="flex-1 py-3 text-white bg-blue-500 rounded-xl font-medium shadow-md active:scale-95 transition">Replay</button>
                    </div>
                </div>
            </div>
        )}

        {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  // 4. Game Screen
  if (screen === 'game' && selectedDifficulty && selectedLevel) {
    return (
      <div className="h-screen w-full bg-paper">
         <SudokuGame 
            difficulty={selectedDifficulty}
            levelId={selectedLevel}
            onBack={handleGameBack}
            onComplete={() => {}} 
            onSettingsOpen={() => setShowSettings(true)}
            onNextLevel={handleNextLevel}
            settings={settings}
         />
         {showSettings && <SettingsModal settings={settings} onToggle={toggleSetting} onReset={resetProgress} onClose={() => setShowSettings(false)} />}
      </div>
    );
  }

  return null;
}

