import { Difficulty, Board, Cell, CellValue } from '../types';

// Simple seeded random number generator (Linear Congruential Generator)
class SeededRandom {
    seed: number;
    constructor(seed: number) {
        this.seed = seed;
    }

    // Returns a number between 0 and 1
    next(): number {
        this.seed = (this.seed * 9301 + 49297) % 233280;
        return this.seed / 233280;
    }
}

// Helper to check if placing num at board[row][col] is valid (Standard Rules)
export function isValid(board: number[][], row: number, col: number, num: number): boolean {
  for (let i = 0; i < 9; i++) {
    // Check Row
    if (board[row][i] === num && i !== col) return false;
    // Check Column
    if (board[i][col] === num && i !== row) return false;
    // Check 3x3 Box
    const boxRow = 3 * Math.floor(row / 3) + Math.floor(i / 3);
    const boxCol = 3 * Math.floor(col / 3) + (i % 3);
    if (board[boxRow][boxCol] === num && (boxRow !== row || boxCol !== col)) return false;
  }
  return true;
}

// Solves/Generates a board using backtracking with Seeded Random
function solveBoard(board: number[][], rng: SeededRandom): boolean {
  for (let row = 0; row < 9; row++) {
    for (let col = 0; col < 9; col++) {
      if (board[row][col] === 0) {
        // Randomize 1-9 check order using seeded RNG
        const nums = [1, 2, 3, 4, 5, 6, 7, 8, 9]
            .map(value => ({ value, sort: rng.next() }))
            .sort((a, b) => a.sort - b.sort)
            .map(({ value }) => value);

        for (const num of nums) {
          if (isValid(board, row, col, num)) {
            board[row][col] = num;
            if (solveBoard(board, rng)) return true;
            board[row][col] = 0;
          }
        }
        return false;
      }
    }
  }
  return true;
}

// Generate a full solved board based on levelId
function generateFullBoard(levelId: number, difficultySeed: number): number[][] {
    const rng = new SeededRandom(levelId + difficultySeed);
    const board = Array.from({ length: 9 }, () => Array(9).fill(0));
    solveBoard(board, rng);
    return board;
}

function getDifficultySeed(diff: Difficulty): number {
    switch(diff) {
        case Difficulty.SuperEasy: return 1000;
        case Difficulty.Easy: return 2000;
        case Difficulty.Normal: return 3000;
        case Difficulty.Hard: return 4000;
        case Difficulty.Intense: return 5000;
        case Difficulty.Impossible: return 6000;
        default: return 0;
    }
}

export function generateLevel(difficulty: Difficulty, levelId: number): { initial: Board, solved: number[][] } {
    const seedBase = getDifficultySeed(difficulty);
    const solvedRaw = generateFullBoard(levelId, seedBase);

    // Create a new RNG for hole removal so the holes are consistent for this level
    const rng = new SeededRandom(levelId + seedBase + 500);

    // Determine number of holes based on difficulty
    let holes = 30; 
    switch(difficulty) {
        case Difficulty.SuperEasy: holes = 25; break;
        case Difficulty.Easy: holes = 35; break;
        case Difficulty.Normal: holes = 38; break; // Reduced from 42 to make it easier
        case Difficulty.Hard: holes = 50; break;
        case Difficulty.Intense: holes = 56; break;
        case Difficulty.Impossible: holes = 60; break;
    }

    // Deep copy for puzzle
    const puzzleRaw = solvedRaw.map(r => [...r]);

    // Remove numbers to create holes
    let attempts = holes;
    while (attempts > 0) {
        const r = Math.floor(rng.next() * 9);
        const c = Math.floor(rng.next() * 9);
        if (puzzleRaw[r][c] !== 0) {
            puzzleRaw[r][c] = 0;
            attempts--;
        }
    }

    // Convert to rich Cell objects
    const initial: Board = puzzleRaw.map((row, rIndex) => 
        row.map((val, cIndex) => ({
            row: rIndex,
            col: cIndex,
            value: val === 0 ? null : (val as CellValue),
            isFixed: val !== 0,
            notes: [],
            isError: false
        }))
    );

    return { initial, solved: solvedRaw };
}

export function checkErrors(current: Board, solved: number[][]): Board {
    return current.map(row => 
        row.map(cell => ({
            ...cell,
            isError: cell.value !== null && cell.value !== solved[cell.row][cell.col]
        }))
    );
}

export function isGameSolved(current: Board): boolean {
    for(let r=0; r<9; r++) {
        for(let c=0; c<9; c++) {
            const cell = current[r][c];
            if (cell.value === null || cell.isError) return false;
        }
    }
    return true;
}

