                        </button>
                    </div>

                    <div className="flex items-center justify-between p-3 rounded-xl bg-stone-50">
                        <div className="flex items-center gap-3 text-stone-700">
                            <Icons.Vibration className="w-5 h-5" />
                            <span>Vibration</span>
                        </div>
